"""Rezepte auf Deutsch : (Titel, Land, Zeit, Portionen, Zusammenfassung, Zutaten, Schritte) je Rezept-ID."""
R = {
    "ndole": ("Ndolé mit Garnelen", "Kamerun", "1 Std. 30", "6 Personen",
              "Das Nationalgericht Kameruns: zarte Ndolé-Blätter in einer Erdnusscreme, mit Garnelen und Fleisch.",
              ["500 g Ndolé-Blätter (tiefgekühlt oder getrocknet)", "500 g rohe geschälte Erdnüsse", "500 g Rindfleisch in Stücken", "200 g getrocknete oder geräucherte Garnelen", "2 Zwiebeln und 4 Knoblauchzehen", "1 Stück Ingwer", "15 cl Erdnussöl", "Salz, Pfeffer, 1 Brühwürfel"],
              ["Die Erdnüsse 15 Minuten kochen, abgießen und mit etwas Wasser zu einer glatten Paste mixen.", "Das Fleisch mit einer Zwiebel, dem Knoblauch, dem Ingwer, Salz und dem Brühwürfel etwa 45 Minuten weich kochen.", "Die Ndolé-Blätter mehrmals spülen (getrocknete 10 Minuten kochen), um die Bitterkeit zu entfernen.", "Die Erdnusspaste in die Fleischbrühe geben und 20 Minuten bei schwacher Hitze unter Rühren köcheln lassen.", "Die Ndolé-Blätter und die Garnelen unterrühren und 15 Minuten köcheln lassen.", "Die zweite Zwiebel in Ringen im heißen Öl braten und kurz vor dem Servieren über das Ndolé geben.", "Mit gebratener reifer Kochbanane, Maniokstangen (Bobolo, Miondo) oder Reis servieren."]),
    "taro-sauce-jaune": ("Taro mit gelber Soße (Achu)", "Kamerun", "2 Std. 30", "6 Personen",
              "Das Festgericht West- und Nordwestkameruns: ein Nest aus gestampftem Taro, gefüllt mit gelber Soße aus Palmöl und Kanwa, umgeben von Rinderhaut, Kutteln und Rindfleisch.",
              ["2 kg Taro", "250 ml Palmöl", "1 EL Kanwa (Steinsalz)", "500 g Rinderhaut, 500 g Rinderfuß", "500 g Kutteln und 500 g Rindfleisch", "1 Räucherfisch", "Gewürze der gelben Soße (Nkui, Djansang, weißer Pfeffer), Chili, Brühwürfel", "Blattgemüse (nach Belieben)"],
              ["Haut, Fuß, Kutteln und Rindfleisch in Stücken mit Salz, Brühwürfeln und Gewürzen langsam weich kochen; die Brühe aufbewahren.", "Den Taro ungeschält waschen und 45 Minuten bis 1 Stunde weich kochen.", "Heiß schälen und mit etwas Kochwasser (oder im Mörser) zu einer glatten, elastischen Masse stampfen.", "Das Kanwa in etwas lauwarmem Wasser auflösen und abseihen.", "Das Palmöl in eine große Schüssel geben und nach und nach das Kanwa-Wasser unterrühren: Das Öl wird gelb und dick.", "Die heiße Fleischbrühe, die gemahlenen Gewürze, Chili und den zerpflückten Räucherfisch unterrühren, bis eine glatte Soße entsteht.", "Den Taro als Nest auf dem Teller anrichten, die gelbe Soße in die Mitte gießen und Fleisch, Haut und Kutteln darum legen."]),
    "poulet-dg": ("Poulet DG", "Kamerun", "1 Std. 15", "6 Personen",
              "Das Huhn „Generaldirektor“: gebratenes Huhn, geschmort mit reifen Kochbananen, Karotten, grünen Bohnen und Paprika.",
              ["1 Huhn in Stücken", "4 reife Kochbananen", "3 Karotten, 200 g grüne Bohnen, 2 Paprikaschoten", "2 Tomaten, 2 Zwiebeln, Knoblauch, Ingwer", "Öl, Salz, Pfeffer, Brühwürfel"],
              ["Das Huhn mit Knoblauch, Ingwer, Salz und Brühwürfel würzen und im Öl anbraten.", "Die Kochbananen in Scheiben schneiden und frittieren; beiseitestellen.", "Im selben Öl Zwiebeln, Tomaten, Karotten und grüne Bohnen 10 Minuten anbraten.", "Das Huhn und ein Glas Wasser dazugeben und 25 Minuten köcheln lassen.", "Paprika und gebratene Kochbananen dazugeben, vorsichtig mischen und weitere 10 Minuten garen."]),
    "eru": ("Eru", "Kamerun", "1 Std. 30", "6 Personen",
              "Eine Spezialität Südwestkameruns: Eru- und Waterleaf-Blätter, langsam in Palmöl gegart, mit Fleisch, Rinderhaut und Räucherfisch.",
              ["500 g geschnittene Eru-Blätter (Okok)", "500 g Waterleaf (oder Spinat)", "500 g Rindfleisch und 300 g Rinderhaut (Kanda)", "1 Räucherfisch und getrocknete Krebse", "300 ml Palmöl", "Chili, Brühwürfel, Salz; mit Water Fufu oder Gari servieren"],
              ["Rindfleisch und Haut in Stücken mit Salz und einem Brühwürfel weich kochen.", "Das gehackte Waterleaf dazugeben: Es gibt viel Wasser ab; 10 Minuten garen.", "Den zerpflückten Räucherfisch und die gemahlenen Krebse dazugeben.", "Das Eru nach und nach unterrühren, dann Palmöl und Chili.", "20 Minuten bei schwacher Hitze unter Rühren garen, bis fast das ganze Wasser verdampft ist.", "Heiß mit Water Fufu oder Gari servieren."]),
    "koki": ("Koki", "Kamerun", "2 Std. 30", "6 Personen",
              "Ein Kuchen aus gestampften Schwarzaugenbohnen mit Palmöl und Blattgemüse, in Bananenblättern gedämpft.",
              ["1 kg Schwarzaugenbohnen", "250 ml Palmöl", "Bananenblätter", "Gehackte Taroblätter oder Spinat", "Chili, Salz, 1 Brühwürfel", "Reife Kochbananen oder Malanga zum Servieren"],
              ["Die Bohnen über Nacht einweichen, reiben, um die Haut zu entfernen, und abspülen.", "Mit etwas lauwarmem Wasser zu einer glatten, dicken Paste mixen.", "Das Palmöl sanft erwärmen (nicht verbrennen) und mit Salz, Chili und Brühwürfel unter die Paste rühren.", "Das gehackte Blattgemüse dazugeben und die Paste gut schlagen.", "Portionen in über der Flamme erweichte Bananenblätter geben und fest verschließen.", "2 Stunden dämpfen. Mit gekochten Kochbananen oder Malanga servieren."]),
    "mbongo-tchobi": ("Mbongo Tchobi (Eintopf mit schwarzen Gewürzen)", "Kamerun", "1 Std. 15", "6 Personen",
              "Die schwarze Soße der Bassa: Fisch in einer Soße aus gerösteten Mbongo-Gewürzen, tief und duftend, mit Kochbanane oder Miondo serviert.",
              ["1,5 kg Fisch (Wolfsbarsch, Karpfen oder Tilapia) in Scheiben", "100 g Mbongo-Gewürze", "2 Tomaten, 1 Zwiebel, 3 Knoblauchzehen, Ingwer", "100 ml Palmöl", "Chili, 1 Brühwürfel, Salz", "Gekochte grüne Kochbananen oder Miondo"],
              ["Das Mbongo in einer trockenen Pfanne rösten, bis es schön schwarz ist (nicht verbrennen), dann mahlen.", "Tomate, Zwiebel, Knoblauch, Ingwer und gemahlenes Mbongo mit etwas Wasser mixen.", "Das Palmöl erhitzen, das Püree hineingeben und 10 Minuten unter Rühren garen.", "500 ml Wasser, Brühwürfel, Salz und Chili dazugeben; aufkochen.", "Die gesäuberten Fischscheiben einlegen und 20 Minuten bei schwacher Hitze garen, ohne zu rühren, dabei den Topf schwenken.", "Mit gekochten Kochbananen oder Miondo servieren."]),
    "beignets-haricots-bouillie": ("Krapfen, Bohnen und Brei", "Kamerun", "2 Std. (+ 1 Std. Gehzeit)", "6 Personen",
              "Das Straßenfrühstück Kameruns: lockere Krapfen, in Öl geschmorte rote Bohnen und ein süßer Maisbrei.",
              ["500 g Weizenmehl, 1 Päckchen Hefe, 100 g Zucker", "Oder eine fertige Krapfenmischung", "500 g rote Bohnen", "1 Zwiebel, Chili, Palm- oder Pflanzenöl", "200 g Maismehl für den Brei", "Zucker, Milch, Zitrone oder Ingwer zum Aromatisieren"],
              ["Krapfen: Mehl, Hefe, Zucker, eine Prise Salz und etwa 400 ml lauwarmes Wasser zu einem klebrigen Teig verrühren; 1 Stunde gehen lassen.", "Teigkugeln von Hand ins heiße Öl fallen lassen und goldbraun frittieren, dabei wenden; abtropfen lassen.", "Bohnen: über Nacht einweichen, 1 Std. 30 kochen und dann mit Zwiebel, Öl, Salz und Chili anbraten.", "Brei: das Maismehl in 500 ml kaltem Wasser anrühren, in 1 Liter kochendes Wasser gießen und 15 Minuten unter Rühren kochen.", "Den Brei süßen und etwas Milch und Zitrone oder Ingwer dazugeben.", "Die Krapfen mit den Bohnen und einer Schale Brei servieren."]),
    "folong-arachide": ("Folong mit Erdnusspaste", "Kamerun", "1 Std.", "6 Personen",
              "Folong-Blätter (Amarant) in einer Erdnusssoße mit Fleisch oder Räucherfisch, ein Klassiker Zentral- und Südkameruns.",
              ["1 kg Folong (oder Spinat)", "300 g Erdnusspaste oder gemahlene rohe Erdnüsse", "500 g Rindfleisch oder 1 Räucherfisch", "Gemahlene getrocknete Krebse", "1 Zwiebel, Chili, Brühwürfel, Salz", "Maniokstangen, Bobolo oder Kochbanane"],
              ["Das Fleisch mit Zwiebel, Salz und Brühwürfel kochen; die Brühe aufbewahren.", "Das Folong waschen, hacken, 5 Minuten in kochendem Wasser blanchieren und gut ausdrücken.", "Die Erdnusspaste in der Brühe auflösen und 20 Minuten bei schwacher Hitze unter Rühren köcheln lassen.", "Zerpflückten Räucherfisch, Krebse und Chili dazugeben.", "Das Folong unterrühren und 15 Minuten köcheln lassen, bis das Erdnussöl aufsteigt.", "Mit Maniokstangen, Bobolo oder Kochbanane servieren."]),
    "kondre": ("Kondré mit Ziegenfleisch", "Kamerun", "1 Std. 45", "6 Personen",
              "Das Festgericht Westkameruns: Ziegenfleisch und Kochbananen, zusammen in einer dicken, würzigen Soße geschmort.",
              ["1,5 kg Ziegenfleisch mit Knochen", "6 grüne Kochbananen", "2 Tomaten, 2 Zwiebeln, Knoblauch, Ingwer", "Nkui-Gewürze, weißer Pfeffer, Djansang", "100 ml Palmöl", "Chili, 2 Brühwürfel, Salz"],
              ["Das Fleisch in Stücken mit Salz, Zwiebel und Brühwürfel 45 Minuten kochen.", "Tomaten, Zwiebel, Knoblauch, Ingwer und Gewürze mixen; mit dem Palmöl zum Fleisch geben.", "Die Kochbananen schälen, in Stücke schneiden und in den Topf geben.", "Wasser bis zur Bedeckung, Chili und den zweiten Brühwürfel dazugeben.", "40 Minuten bei schwacher Hitze garen: Die Kochbananen binden die Soße. Abschmecken und heiß servieren."]),
    "ndomba-poisson": ("Fisch-Ndomba (in Bananenblättern)", "Kamerun", "1 Std. 15", "4 Personen",
              "Fisch, in Gewürzen und Tomate mariniert, in Bananenblätter gewickelt und gedämpft, zart und duftend.",
              ["1 kg Fisch (Tilapia, Wolfsbarsch, Makrele)", "Bananenblätter", "2 Tomaten, 1 Zwiebel, Knoblauch, Ingwer, Petersilie", "Gewürze (Djansang, weißer Pfeffer, nach Belieben Mbongo)", "Chili, Brühwürfel, Salz, etwas Öl", "Bobolo, Miondo oder Kochbanane"],
              ["Den gesäuberten Fisch in Stücke schneiden und salzen.", "Tomaten, Zwiebel, Knoblauch, Ingwer, Petersilie, Gewürze und Chili mixen; den Fisch damit bedecken und 30 Minuten ziehen lassen.", "Die Bananenblätter über der Flamme weich machen.", "Fisch und Marinade in die Mitte legen, einen Schuss Öl und den Brühwürfel dazugeben und zu einem festen Päckchen falten.", "Dämpfen oder in einem Topf mit etwas Wasser und Deckel 40 Minuten garen.", "Am Tisch öffnen und mit Bobolo, Miondo oder Kochbanane servieren."]),
    "attieke-poisson": ("Attiéké mit gegrilltem Fisch", "Elfenbeinküste", "45 Min.", "4 Personen",
              "Ein Klassiker des Straßenessens in Abidjan: marinierter gegrillter Fisch mit Attiéké und einer frischen Chilisoße.",
              ["1 kg Attiéké", "2 ganze Fische (Tilapia, Makrele oder Wolfsbarsch)", "3 Tomaten und 2 Zwiebeln", "1 bis 2 frische Chilis", "1 Stück Ingwer und 3 Knoblauchzehen", "Öl, Salz, Brühwürfel, Zitronensaft"],
              ["Die Fische schuppen, ausnehmen und auf beiden Seiten einschneiden.", "Knoblauch, Ingwer, eine halbe Zwiebel, etwas Chili, Brühwürfel, Salz und Öl mixen und die Fische damit bestreichen. 30 Minuten marinieren.", "Die Fische auf dem Grill oder im Ofen (220 °C) etwa 12 Minuten pro Seite garen.", "Tomaten, Zwiebeln und Chili fein hacken und mit Salz, Zitrone und einem Schuss Öl würzen.", "Den Attiéké dämpfen oder in der Mikrowelle erwärmen und mit einer Gabel auflockern.", "Den Fisch auf dem Attiéké mit der frischen Soße und nach Belieben Alloco servieren."]),
    "alloco": ("Alloco (frittierte Kochbananen)", "Elfenbeinküste", "20 Min.", "4 Personen",
              "Sehr reife Kochbananen, goldbraun und karamellisiert frittiert, serviert mit Fisch, Eiern oder einer scharfen Soße.",
              ["4 sehr reife Kochbananen (gelbe Schale mit schwarzen Flecken)", "Erdnussöl zum Frittieren", "Salz, Chili und Zwiebel für die Soße"],
              ["Die Kochbananen schälen und in Scheiben oder schräge Stücke schneiden.", "Leicht salzen.", "In heißem Öl (170 °C) 3 bis 4 Minuten frittieren, bis sie schön goldbraun sind.", "Auf Küchenpapier abtropfen lassen und heiß mit einer Soße aus Chili, Zwiebel und Tomate servieren."]),
    "kedjenou": ("Kedjenou mit Huhn", "Elfenbeinküste", "1 Std. 15", "6 Personen",
              "Ivorisches Huhn, langsam im eigenen Saft mit Tomaten, Zwiebeln, Auberginen und Chili gegart, ohne einen Tropfen Wasser.",
              ["1,5 kg Huhn (wenn möglich Freiland)", "4 Tomaten, 2 Zwiebeln, 2 Auberginen", "Knoblauch, Ingwer, Chili", "Thymian, Lorbeer, 1 Brühwürfel, Salz", "Attiéké oder Reis zum Servieren"],
              ["Das Huhn in Stücke schneiden und mit allem geschnittenen Gemüse in einen Schmortopf (oder Tontopf) geben.", "Zerdrückten Knoblauch und Ingwer, Chili, Thymian, Lorbeer, Brühwürfel und Salz dazugeben.", "Den Topf fest verschließen, ohne Wasser hinzuzufügen.", "1 Stunde bei schwacher Hitze garen und den Topf alle 10 Minuten schwenken, ohne ihn zu öffnen.", "Die Soße soll kurz und duftend sein. Mit Attiéké oder Reis servieren."]),
    "sauce-graine": ("Palmnusssoße (Sauce graine)", "Elfenbeinküste", "1 Std. 30", "6 Personen",
              "Eine rote, cremige Palmnusssoße mit Fleisch, Räucherfisch und Krabben, serviert mit Kochbananen-Foutou oder Reis.",
              ["800 g Palmnusscreme", "800 g Fleisch (Rind, Huhn oder Hammel)", "1 Räucherfisch und einige Krabben", "2 Zwiebeln, 2 Tomaten, 1 Aubergine", "Chili, Brühwürfel, Salz", "Kochbananen-Foutou oder Reis"],
              ["Das Fleisch mit einer Zwiebel, Salz und Brühwürfel in 1,5 Litern Wasser 30 Minuten kochen.", "Die Palmnusscreme im Kochwasser auflösen und Tomaten und Aubergine im Ganzen dazugeben.", "Nach 15 Minuten Tomaten und Aubergine herausnehmen, zerdrücken und wieder in die Soße geben.", "Räucherfisch, Krabben und Chili dazugeben; 40 Minuten bei schwacher Hitze köcheln lassen.", "Die Soße ist fertig, wenn das rote Öl an die Oberfläche steigt. Mit Foutou oder Reis servieren."]),
    "garba": ("Garba", "Elfenbeinküste", "30 Min.", "4 Personen",
              "Das Lieblingsstraßenessen Abidjans: Attiéké mit frittiertem Thunfisch (oder Fisch), Zwiebel, Tomate und viel Chili.",
              ["1 kg Attiéké", "800 g Thunfisch oder fester Fisch (Tilapia)", "2 Zwiebeln, 2 Tomaten, frische Chilis", "Öl zum Frittieren", "1 Brühwürfel, Salz, Pfeffer"],
              ["Den Fisch in große Stücke schneiden, salzen und in sehr heißem Öl knusprig frittieren.", "Zwiebeln und Tomaten schneiden, Chilis hacken.", "Den Attiéké mit etwas Wasser dämpfen oder in der Mikrowelle erwärmen, auflockern und eine Prise Brühwürfel dazugeben.", "Den Attiéké mit Fisch, Zwiebeln, Tomaten, Chili und etwas Frittieröl servieren."]),
    "pondu": ("Pondu (Saka-Saka)", "DR Kongo", "2 Std.", "6 Personen",
              "Gestampfte Maniokblätter, langsam mit Palmöl, Zwiebel und Salzfisch geköchelt.",
              ["1 kg Pondu (tiefgekühlte gestampfte Maniokblätter)", "300 g Salz- oder Räucherfisch", "15 cl rotes Palmöl", "2 Zwiebeln, 3 Knoblauchzehen", "1 Aubergine oder einige Okras (nach Belieben)", "Salz, Chili, Brühwürfel"],
              ["Den Salzfisch einige Stunden wässern, um ihn zu entsalzen, dann zerpflücken.", "Das Pondu in einen großen Topf geben, mit Wasser bedecken und mindestens 1 Stunde bei mittlerer Hitze kochen, bei Bedarf Wasser nachgießen.", "Gehackte Zwiebeln und Knoblauch, den Fisch und die Aubergine dazugeben und 30 Minuten garen.", "Das Palmöl dazugießen, Salz, Chili und Brühwürfel dazugeben. Weitere 20 Minuten köcheln lassen, bis das Wasser fast aufgesogen ist.", "Mit Fufu, Chikwangue oder Reis servieren."]),
    "fumbwa": ("Fumbwa", "DR Kongo", "1 Std. 15", "6 Personen",
              "Fein geschnittene Fumbwa-Blätter, in einer Erdnuss-Palmöl-Soße mit Salzfisch gegart.",
              ["500 g Fumbwa (Gnetum-Blätter)", "250 g Erdnusspaste", "300 g Salz- oder Räucherfisch", "100 ml Palmöl", "2 Zwiebeln, 2 Tomaten, Chili", "Chikwangue oder Fufu"],
              ["Den Fisch wässern, entsalzen und zerpflücken.", "Das Fumbwa waschen und 20 Minuten kochen; abgießen.", "Zwiebeln und Tomaten im Palmöl anbraten.", "Die in 500 ml Wasser aufgelöste Erdnusspaste dazugeben, dann Fumbwa und Fisch.", "30 Minuten bei schwacher Hitze unter Rühren köcheln lassen; Chili dazugeben.", "Mit Chikwangue oder Fufu servieren."]),
    "egusi-foufou": ("Egusi-Suppe mit Fufu", "Nigeria", "1 Std.", "6 Personen",
              "Eine dicke Soße aus gemahlenen Melonenkernen, Blattgemüse und Fleisch, serviert mit Fufu oder gestampftem Yams.",
              ["300 g gemahlene Egusi-Kerne", "500 g Fleisch (Rind, Ziege) und etwas Räucherfisch", "200 g Spinat oder Bitterblätter", "15 cl rotes Palmöl", "2 Zwiebeln, Chili, gemahlene getrocknete Garnelen", "Fufu-Mehl oder Mehl aus gestampftem Yams zum Servieren"],
              ["Das Fleisch mit einer Zwiebel, Salz und Brühwürfel weich kochen; die Brühe aufbewahren.", "Das gemahlene Egusi mit einer gemixten Zwiebel und etwas Wasser zu einer Paste verrühren.", "Das Palmöl erhitzen und die Egusi-Paste 10 Minuten unter Rühren braten, bis sie kleine Flocken bildet.", "Brühe, Fleisch, Räucherfisch, Garnelen und Chili dazugeben. 20 Minuten köcheln lassen.", "Das geschnittene Blattgemüse dazugeben und weitere 5 Minuten garen.", "Für das Fufu das Mehl in kochendes Wasser geben und kräftig rühren, bis ein glatter, fester Teig entsteht. Mit der Suppe servieren."]),
    "pepper-soup": ("Pepper Soup mit Ziegenfleisch", "Nigeria", "1 Std. 30", "6 Personen",
              "Eine klare, feurige, wohltuende Suppe aus Ziegenfleisch und Pepper-Soup-Gewürzen, pur oder mit Yams serviert.",
              ["1,5 kg Ziegenfleisch mit Knochen", "Pepper-Soup-Gewürzmischung (Calabash-Muskat, Paradieskörner…)", "Scotch-Bonnet-Chilis, 1 Zwiebel", "Utazi-Blätter oder afrikanisches Basilikum", "2 Brühwürfel, Salz", "Gekochter Yams (nach Belieben)"],
              ["Das Fleisch waschen und mit Zwiebel, Salz und Brühwürfeln in einen Topf geben; 10 Minuten Saft ziehen lassen.", "Mit 2 Litern Wasser bedecken und 1 Stunde weich kochen.", "Die gemahlenen Gewürze und zerdrückten Chilis dazugeben; 15 Minuten kochen.", "Die gehackten Blätter zum Schluss dazugeben.", "Sehr heiß servieren, mit Yams für eine vollständige Mahlzeit."]),
    "eba-sauce-gombo": ("Okrasoße mit Eba", "Westafrika", "50 Min.", "4 Personen",
              "Eine samtige Okrasoße mit Räucherfisch und Palmöl, serviert mit Eba (Gari-Teig).",
              ["500 g frische oder tiefgekühlte Okra", "300 g Räucherfisch und 300 g Fleisch", "10 cl rotes Palmöl", "1 Zwiebel, Chili, getrocknete Garnelen", "500 g Gari für das Eba"],
              ["Das Fleisch mit Zwiebel, Salz und Brühwürfel kochen; die Brühe aufbewahren.", "Die Okra in dünne Scheiben schneiden (oder reiben).", "Palmöl, zerpflückten Räucherfisch, Garnelen und Chili in die Brühe geben. 10 Minuten kochen.", "Die Okra dazugeben und 5 bis 8 Minuten bei schwacher Hitze ohne Deckel garen, damit sie grün und samtig bleibt.", "Für das Eba das Gari vom Herd genommen in kochendes Wasser geben, eine Minute quellen lassen und mit einem Spatel zu einem festen Teig verarbeiten."]),
    "griot-bananes-pesees": ("Griot mit Bananes pesées", "Haiti", "2 Std. (plus Marinieren)", "6 Personen",
              "Das Festgericht Haitis: Schweinefleisch, in Zitrusfrüchten und Epis mariniert, geschmort und dann frittiert, mit plattgedrückten frittierten grünen Kochbananen.",
              ["1,5 kg Schweineschulter in Würfeln", "Saft von 2 Bitterorangen (oder Orangen und Limetten)", "Epis: Petersilie, Thymian, Knoblauch, Frühlingszwiebel, Scotch-Bonnet-Chili", "3 grüne Kochbananen", "Öl zum Frittieren"],
              ["Das Schweinefleisch mit dem Zitrussaft waschen und mindestens 4 Stunden (am besten über Nacht) mit dem gemixten Epis marinieren.", "Das Fleisch mit der Marinade und etwas Wasser zugedeckt 1 Stunde garen, dann ohne Deckel, bis die Flüssigkeit verdampft ist.", "Die Fleischstücke in heißem Öl gut braun frittieren.", "Die grünen Kochbananen schälen, in Stücke schneiden und 4 Minuten frittieren.", "Zwischen zwei Brettchen plattdrücken und erneut knusprig frittieren.", "Das Griot mit den Bananes pesées und Pikliz (scharf eingelegter Kohl mit Karotten) servieren."]),
    "diri-djon-djon": ("Diri Djon Djon (Reis mit schwarzen Pilzen)", "Haiti", "50 Min.", "6 Personen",
              "Der schwarze Reis für besondere Anlässe in Haiti, gekocht im duftenden Wasser der Djon-Djon-Pilze, mit Erbsen.",
              ["30 g getrocknete Djon-Djon-Pilze", "500 g Langkornreis", "1 Tasse Erbsen (oder Limabohnen)", "Epis (Knoblauch, Petersilie, Frühlingszwiebel, Paprika, Thymian), 1 Chili", "1 Brühwürfel, Gewürznelken, Salz", "3 EL Öl oder Butter"],
              ["Die Djon Djon 20 Minuten in 1 Liter kochendem Wasser einweichen, dann abseihen: das schwarze Wasser aufbewahren.", "Das Epis im Öl anbraten, Erbsen und gewaschenen Reis dazugeben und 2 Minuten rühren.", "Das Djon-Djon-Wasser (etwa 750 ml), den Brühwürfel, die Nelken, Salz und die ganze Chili dazugeben.", "Ohne Deckel bei mittlerer Hitze kochen, bis das Wasser aufgesogen ist.", "Zudecken und 20 Minuten bei sehr schwacher Hitze fertig garen. Mit Griot oder Huhn servieren."]),
    "soup-joumou": ("Soup Joumou", "Haiti", "2 Std. 30", "8 Personen",
              "Die Suppe der Freiheit, in Haiti jedes Jahr am 1. Januar serviert: eine Kürbissuppe mit Rindfleisch, Gemüse und Nudeln.",
              ["1 kg Suppenfleisch und -knochen vom Rind", "1 Kürbis von etwa 1,5 kg", "Kohl, Karotten, Kartoffeln, Rübe, Lauch", "Epis, Thymian, Gewürznelken, 1 Chili", "200 g Nudeln (Makkaroni oder Spaghetti)", "Limettensaft zum Waschen des Fleisches"],
              ["Das Fleisch mit Limettensaft waschen, mit Epis marinieren und 1 Stunde in 3 Litern Wasser kochen.", "Den geschälten Kürbis getrennt kochen, mit etwas Brühe pürieren und in den Topf geben.", "Geschnittenes Gemüse, Thymian, Nelken und die ganze Chili dazugeben; 30 Minuten kochen.", "Die Nudeln dazugeben und weitere 10 Minuten kochen.", "Abschmecken und heiß mit einer Scheibe Brot servieren."]),
    "mafe": ("Mafé (Erdnusseintopf)", "Senegal und Mali", "1 Std. 15", "6 Personen",
              "Ein wohltuender Eintopf aus Fleisch und Gemüse in einer Soße aus Erdnusspaste und Tomate, mit Reis serviert.",
              ["1 kg Rind-, Lamm- oder Hühnerfleisch", "250 g Erdnusspaste", "2 EL Tomatenmark", "2 Zwiebeln, 3 Knoblauchzehen, 1 Chili", "Karotten, Süßkartoffel, Kohl oder Maniok", "Reis zum Servieren"],
              ["Das Fleisch in etwas Öl mit den Zwiebeln und dem Knoblauch anbraten.", "Das Tomatenmark dazugeben und 5 Minuten anrösten.", "Die Erdnusspaste in einem Liter heißem Wasser auflösen und über das Fleisch gießen.", "Das Gemüse in großen Stücken, die ganze Chili, Salz und Brühwürfel dazugeben.", "45 Minuten bei schwacher Hitze köcheln lassen und ab und zu umrühren, bis das Öl an die Oberfläche steigt.", "Mit weißem Reis servieren."]),
    "riz-jollof": ("Jollof-Reis", "Nigeria und Ghana", "1 Std.", "6 Personen",
              "Der Festreis Westafrikas: in einer rauchigen, scharfen Tomaten-Paprika-Soße gegart, mit Huhn oder frittiertem Fisch serviert.",
              ["600 g Parboiled-Langkornreis", "4 Tomaten, 2 rote Paprika, 1 Scotch-Bonnet-Chili", "3 EL Tomatenmark", "2 Zwiebeln", "Currypulver, Thymian, Lorbeer, 2 Brühwürfel", "125 ml Pflanzenöl"],
              ["Tomaten, Paprika, Chili und eine Zwiebel zu einem glatten Püree mixen.", "Die zweite Zwiebel in Ringen im Öl anbraten, das Tomatenmark dazugeben und 5 Minuten anrösten.", "Das Püree dazugießen und 15 Minuten bei mittlerer Hitze einkochen, bis die Soße andickt.", "Curry, Thymian, Lorbeer, Brühwürfel, Salz und 500 ml Wasser oder Brühe dazugeben.", "Den gewaschenen Reis dazugeben, mit Alufolie und Deckel abdecken und 30 Minuten bei schwacher Hitze garen, ohne zu rühren.", "Zum Schluss vorsichtig umrühren; eine leichte Kruste am Boden sorgt für den begehrten Rauchgeschmack."]),
    "thieboudienne": ("Thieboudienne", "Senegal", "2 Std.", "6 Personen",
              "Das Nationalgericht Senegals: mit Petersilie gefüllter Fisch, zartes Gemüse und Bruchreis, in der roten Brühe gegart.",
              ["1,5 kg fester Fisch (Zackenbarsch oder Brasse)", "600 g Bruchreis", "100 g Tomatenmark", "Maniok, Kohl, Karotten, Aubergine, Okra", "Petersilie, Knoblauch, Chili (Füllung: Rof)", "Geräucherter oder getrockneter Fisch (Guedj)", "150 ml Öl"],
              ["Petersilie, Knoblauch, Chili und etwas Zwiebel zerstoßen; den Fisch durch Einschnitte füllen.", "Den Fisch im Öl braten und herausnehmen; Zwiebeln und Tomatenmark 10 Minuten anbraten.", "2 Liter Wasser, den getrockneten Fisch, das Gemüse und die Würze dazugeben; 30 Minuten kochen.", "Den Fisch für 15 Minuten wieder hineingeben, dann Fisch und Gemüse herausnehmen und warm halten.", "Den gewaschenen Reis 15 Minuten dämpfen, dann in die abgeseihte Brühe geben und 25 Minuten bei schwacher Hitze garen.", "Den Reis auf einer großen Platte anrichten, Fisch und Gemüse darauflegen."]),
    "poulet-yassa": ("Huhn Yassa", "Senegal", "1 Std. (+ 2 Std. Marinieren)", "6 Personen",
              "Huhn, in Zitrone und Senf mariniert, gegrillt und dann in einem Berg zarter Zwiebeln geschmort.",
              ["1,5 kg Hühnerteile", "1 kg Zwiebeln", "Saft von 4 Zitronen", "3 EL Senf", "Knoblauch, Chili, 2 Brühwürfel, Pfeffer", "Grüne Oliven (nach Belieben) und weißer Reis"],
              ["Zitronensaft, Senf, Knoblauch, Pfeffer, zerbröselte Brühwürfel und Zwiebelringe mischen.", "Das Huhn darin mindestens 2 Stunden (am besten über Nacht) marinieren.", "Das Huhn abtropfen lassen und im Ofen oder auf dem Grill schön braun grillen.", "Die Zwiebeln der Marinade 20 Minuten in etwas Öl weich dünsten, dann den Rest der Marinade dazugießen.", "Huhn, ganze Chili und Oliven dazugeben; 20 Minuten köcheln lassen.", "Mit weißem Reis servieren."]),
    "poulet-moambe": ("Huhn Moambe", "DR Kongo und Kongo", "1 Std. 15", "6 Personen",
              "Das kongolesische Sonntagshuhn, in Palmnusssoße (Moambe) geschmort, mit Reis oder Fufu serviert.",
              ["1,5 kg Hühnerteile", "800 g Moambe-Soße (Palmnusscreme)", "2 Zwiebeln, 3 Knoblauchzehen", "2 Tomaten oder 2 EL Tomatenmark", "1 Chili, 1 Brühwürfel, Salz", "Reis, Fufu oder Chikwangue"],
              ["Das Huhn salzen, pfeffern und in einem Topf anbraten.", "Zwiebeln und Knoblauch, dann die Tomaten dazugeben; 5 Minuten anbraten.", "Die Palmnusscreme in 500 ml heißem Wasser auflösen und über das Huhn gießen.", "Brühwürfel und ganze Chili dazugeben und 45 Minuten bei schwacher Hitze köcheln lassen, bis die Soße dick ist und das Öl aufsteigt.", "Mit Reis, Fufu oder Chikwangue servieren."]),
    "liboke-poisson": ("Fisch-Liboké", "DR Kongo und Kongo", "1 Std.", "4 Personen",
              "Fisch nach kongolesischer Art, mit Tomate, Zwiebel und Chili gewürzt, in Bananenblatt-Päckchen über Glut gegart.",
              ["1 kg Fisch (Tilapia, Nilbarsch, Wels)", "Bananenblätter", "2 Tomaten, 2 Zwiebeln, Knoblauch, Chili", "2 EL Palmöl", "1 Brühwürfel, Salz", "Chikwangue oder Reis zum Servieren"],
              ["Den Fisch säubern, in Stücke schneiden und salzen.", "Tomaten und Zwiebeln würfeln, Knoblauch und Chili zerdrücken; mit Palmöl und Brühwürfel mischen.", "Die Bananenblätter über der Flamme weich machen.", "Den mit der Mischung bedeckten Fisch auf die Blätter legen und zu Päckchen binden.", "Über Glut, auf dem Grill oder im Ofen bei 200 °C 35 bis 40 Minuten garen.", "In den Blättern mit Chikwangue oder Reis servieren."]),
    "poulet-jerk": ("Jerk Chicken", "Jamaika", "1 Std. (+ 4 Std. Marinieren)", "6 Personen",
              "Jamaikas gegrilltes Huhn, mariniert in einer Paste aus Scotch-Bonnet-Chili, Piment und Thymian, mit rauchigem Geschmack.",
              ["1,5 kg Hähnchenschenkel", "Jerk-Marinade (oder 2 Scotch-Bonnet-Chilis)", "1 EL Pimentkörner", "Thymian, Knoblauch, Ingwer, Zwiebeln", "Saft von 2 Limetten, Sojasoße, brauner Zucker", "Rice and Peas oder frittierte Kochbananen zum Servieren"],
              ["Chili, gemahlenen Piment, Thymian, Knoblauch, Ingwer, Zwiebeln, Limettensaft, Sojasoße und braunen Zucker mixen.", "Das Huhn einschneiden, mit der Marinade bestreichen und mindestens 4 Stunden (am besten über Nacht) ruhen lassen.", "Bei mittlerer Hitze mit geschlossenem Deckel 35 bis 40 Minuten grillen und oft wenden (oder bei 200 °C im Ofen garen).", "Während des Garens mit Marinade bestreichen; die Haut soll gut gebräunt sein.", "Mit Rice and Peas oder frittierten Kochbananen servieren."]),
    "ackee-morue": ("Ackee und Stockfisch", "Jamaika", "45 Min. (+ 1 Nacht Wässern)", "4 Personen",
              "Jamaikas Nationalgericht: die Ackee-Frucht, zart wie Rührei, mit Stockfisch, Paprika und Zwiebeln gebraten.",
              ["1 Dose Ackee (540 g)", "300 g Stockfisch oder Salzfisch", "1 Zwiebel, 1 Paprika, 2 Tomaten", "1 Scotch-Bonnet-Chili, Thymian", "Öl, schwarzer Pfeffer", "Frittierte Kochbananen oder gekochte grüne Bananen"],
              ["Den Fisch über Nacht in kaltem Wasser wässern, dann 15 Minuten kochen, abgießen und zerpflücken.", "Zwiebel, Paprika, Chili und Thymian 5 Minuten im Öl anbraten.", "Tomaten und zerpflückten Fisch dazugeben und 5 Minuten garen.", "Die Ackee abtropfen lassen und ganz vorsichtig unterheben, damit sie nicht zerfällt. 3 Minuten erwärmen.", "Pfeffern und mit frittierten Kochbananen oder grünen Bananen servieren."]),
    "riz-et-pois": ("Rice and Peas (Reis mit Bohnen)", "Jamaika", "1 Std. 15", "6 Personen",
              "Jamaikas Sonntagsbeilage: Reis, mit roten Kidneybohnen in Kokosmilch, Thymian und einer ganzen Scotch-Bonnet-Chili gegart.",
              ["1 Dose rote Kidneybohnen (oder 250 g getrocknete)", "1 Dose Kokosmilch", "400 g Langkornreis", "Thymian, Piment, 2 Frühlingszwiebeln, Knoblauch", "1 ganze Scotch-Bonnet-Chili"],
              ["Getrocknete Bohnen über Nacht einweichen und 1 Stunde kochen; das Kochwasser aufbewahren.", "In einem Topf Bohnen, Kokosmilch, 500 ml Wasser (oder Kochwasser), Knoblauch, Thymian, Piment und Frühlingszwiebeln vermischen.", "Aufkochen, salzen, dann den gewaschenen Reis und die ganze Chili (nicht aufstechen) dazugeben.", "Zudecken und 25 Minuten bei schwacher Hitze garen, bis die Flüssigkeit aufgesogen ist.", "Chili und Thymian entfernen, mit einer Gabel auflockern und mit Jerk Chicken oder Ziegencurry servieren."]),
    "curry-chevre": ("Ziegencurry", "Jamaika", "2 Std. (+ 2 Std. Marinieren)", "6 Personen",
              "Das Festcurry der Karibik: Ziegenfleisch, langsam in jamaikanischem Curry mit Kartoffeln und Scotch-Bonnet-Chili geschmort.",
              ["1,5 kg Ziegenfleisch mit Knochen", "3 EL Currypulver", "Zwiebeln, Knoblauch, Ingwer, Thymian, Frühlingszwiebeln", "1 Scotch-Bonnet-Chili, Piment", "3 Kartoffeln", "Rice and Peas zum Servieren"],
              ["Das Fleisch mit 2 EL Curry, Knoblauch, Ingwer, Zwiebel, Thymian, Salz und Pfeffer mindestens 2 Stunden marinieren.", "Den letzten Löffel Curry 1 Minute in heißem Öl rösten.", "Das Fleisch dazugeben und gut anbraten.", "Mit Wasser bedecken, die ganze Chili und den Piment dazugeben; 1 Std. 15 bei schwacher Hitze schmoren.", "Die gewürfelten Kartoffeln dazugeben und 30 Minuten garen: Sie binden die Soße.", "Mit Rice and Peas servieren."]),
    "pozole": ("Pozole rojo", "Mexiko", "2 Std.", "8 Personen",
              "Mexikos Festsuppe: Schweinefleisch und Hominy-Mais in einer roten Chilibrühe, garniert mit Kohl, Radieschen und Limette.",
              ["1,5 kg Schweineschulter", "1 Glas weißer Hominy-Mais", "Getrocknete Guajillo- oder Ancho-Chilis (oder Chilipulver)", "1 Zwiebel, 1 Knolle Knoblauch, Oregano, Kreuzkümmel", "Fein geschnittener Kohl, Radieschen, Zwiebel, Limetten", "Tostadas oder Tortillas zum Servieren"],
              ["Das Schweinefleisch in Stücken mit Zwiebel, Knoblauch und Salz in 4 Litern Wasser 1 Std. 30 bei schwacher Hitze kochen.", "Die entkernten Chilis 20 Minuten in heißem Wasser einweichen, dann mit etwas Knoblauch und Oregano mixen; abseihen.", "Die Chilisoße und den abgespülten Mais in die Brühe geben; 30 Minuten köcheln lassen.", "Abschmecken und den Kreuzkümmel dazugeben.", "In großen Schalen servieren, mit Kohl, Radieschen, Zwiebel, Oregano und Limette extra, dazu Tostadas."]),
    "arepas": ("Arepas mit Käse", "Kolumbien und Venezuela", "30 Min.", "8 Arepas",
              "Die goldenen Maisfladen Kolumbiens und Venezuelas, außen knusprig, innen weich, mit Käse gefüllt.",
              ["2 Tassen vorgekochtes Maismehl (Masarepa)", "2½ Tassen lauwarmes Wasser, 1 TL Salz", "200 g weißer Käse (Queso blanco oder Costeño)", "Butter oder Öl", "Oder fertige Arepas zum Aufwärmen"],
              ["Das lauwarme Wasser mit Salz mischen, das Mehl nach und nach dazugeben und zu einem glatten Teig kneten; 5 Minuten ruhen lassen.", "Die Hälfte des geriebenen Käses in den Teig geben (nach Belieben).", "8 Kugeln formen und zu 1,5 cm dicken Fladen drücken.", "In einer gebutterten Pfanne bei mittlerer Hitze 6 bis 8 Minuten pro Seite backen, bis sie hohl klingen.", "Seitlich aufschneiden, mit Käse füllen und heiß servieren."]),
    "pupusas": ("Pupusas mit Käse und Loroco", "El Salvador", "40 Min.", "10 Pupusas",
              "Die gefüllten Maisfladen El Salvadors, mit Käse und Loroco-Blüten, serviert mit Curtido-Krautsalat.",
              ["3 Tassen Masa-Maismehl (Maseca)", "250 g schmelzender Käse (Quesillo, Mozzarella)", "100 g Loroco", "Curtido: Kohl, Karotte, Zwiebel, Oregano, Essig", "Tomatensoße zum Servieren"],
              ["Am Vortag das Curtido zubereiten: geriebener Kohl und Karotte, Zwiebel, Oregano, Salz und Essig.", "Die Masa mit etwa 2 Tassen lauwarmem Wasser und Salz zu einem weichen, nicht klebenden Teig verarbeiten.", "Geriebenen Käse und gehackten Loroco mischen.", "Eine Teigkugel formen, aushöhlen, füllen, verschließen und zwischen den Händen sanft flach drücken.", "Auf einer heißen, ungefetteten Platte 3 bis 4 Minuten pro Seite backen. Mit Curtido und Tomatensoße servieren."]),
    "feijoada": ("Feijoada", "Brasilien", "3 Std. (+ 1 Nacht Einweichen)", "8 Personen",
              "Brasiliens großer Eintopf aus schwarzen Bohnen, mit mehreren Schweinefleischsorten und Wurst geschmort, serviert mit Reis und Orangen.",
              ["1 kg schwarze Bohnen", "1,5 kg Schweinefleisch: Rippchen, Schulter, Fuß oder Schwanz", "400 g Chorizo oder Räucherwurst", "2 Zwiebeln, 1 Knolle Knoblauch, Lorbeer", "Weißer Reis, Orangen, gebratener Grünkohl", "Geröstetes Maniokmehl (Farofa)"],
              ["Die Bohnen über Nacht einweichen; gepökeltes Fleisch gegebenenfalls wässern.", "Die Bohnen mit dem Lorbeer in reichlich Wasser 1 Stunde kochen.", "Fleisch in Stücken und Chorizo anbraten und zu den Bohnen geben.", "Zwiebeln und Knoblauch anbraten, eine Kelle Bohnen dazugeben, zerdrücken und wieder in den Topf geben.", "1 Std. 30 bei schwacher Hitze köcheln lassen, bis die Soße dick und das Fleisch zart ist.", "Mit Reis, gebratenem Grünkohl, Farofa und Orangenspalten servieren."]),
    "couscous-legumes": ("Couscous mit Gemüse und Lamm", "Marokko", "1 Std. 30", "6 Personen",
              "Der Freitagscouscous: feiner, lockerer Grieß, eine gewürzduftende Brühe, Lamm und sieben Gemüsesorten.",
              ["500 g feiner oder mittlerer Couscous", "1 kg Lamm-, Hammel- oder Hühnerfleisch", "Karotten, Rüben, Zucchini, Kohl, Kürbis", "1 Dose Kichererbsen", "Ingwer, Kurkuma, Zimt, Pfeffer, Koriander", "2 Zwiebeln, 2 Tomaten, Olivenöl, Butter"],
              ["Das Fleisch mit Zwiebeln, Tomaten, Olivenöl und Gewürzen im unteren Teil des Couscoustopfs anbraten.", "Mit 2,5 Litern Wasser bedecken und 45 Minuten kochen.", "Das Gemüse dazugeben, zuerst das festeste (Karotten, Rüben), dann Zucchini, Kohl und Kürbis; die Kichererbsen dazugeben.", "Den Grieß mit Salzwasser befeuchten, auflockern und zweimal 15 Minuten über der Brühe dämpfen.", "Den Grieß mit Butter auflockern, als Kuppel mit Fleisch und Gemüse anrichten und die Brühe getrennt servieren."]),
    "harira": ("Harira", "Marokko", "1 Std. 30", "8 Personen",
              "Marokkos Ramadansuppe: Tomaten, Linsen, Kichererbsen, Fleisch und frische Kräuter, gebunden und mit Zitrone vollendet.",
              ["300 g gewürfeltes Lamm-, Hammel- oder Rindfleisch", "150 g braune Linsen", "1 Dose Kichererbsen", "1 kg Tomaten oder 2 EL Tomatenmark", "Sellerie, Koriander, Petersilie, Zwiebel", "Ingwer, Zimt, Kurkuma, Pfeffer", "2 EL Mehl, 1 Zitrone, Fadennudeln (nach Belieben)"],
              ["Das Fleisch mit Zwiebel und Gewürzen in etwas Öl anbraten.", "Gehackten Sellerie und Kräuter, pürierte Tomaten und 2,5 Liter Wasser dazugeben.", "Die abgespülten Linsen dazugeben und 45 Minuten kochen.", "Kichererbsen und Fadennudeln dazugeben und 10 Minuten kochen.", "Das Mehl mit etwas kaltem Wasser anrühren und unter Rühren einlaufen lassen; 10 Minuten kochen, bis die Suppe sämig ist.", "Mit Zitrone, Datteln und hart gekochten Eiern servieren."]),
    "kelewele": ("Kelewele", "Ghana", "25 Min.", "4 Personen",
              "Würfel reifer Kochbanane, in Ingwer und Chili mariniert und karamellisiert frittiert: Ghanas Straßensnack.",
              ["4 sehr reife Kochbananen", "Frischer Ingwer, Knoblauch", "Cayennepfeffer oder frische Chili", "Öl zum Frittieren", "Geröstete Erdnüsse zum Servieren"],
              ["Die Kochbananen schälen und in Würfel oder schräge Stücke schneiden.", "Ingwer, Knoblauch und Chili mit etwas Salz und Wasser zerstoßen.", "Die Kochbanane mit der Mischung vermengen und 15 Minuten ziehen lassen.", "In kleinen Mengen in heißem Öl frittieren, bis die Kochbanane tief goldbraun und karamellisiert ist.", "Abtropfen lassen und heiß mit gerösteten Erdnüssen servieren."]),
    "jus-bissap": ("Bissap-Saft", "Senegal und Westafrika", "20 Min. (+ 2 Std. Kühlen)", "2 Liter",
              "Das erfrischende rote Getränk Westafrikas aus Hibiskusblüten, aromatisiert mit Minze, Ingwer oder Vanille.",
              ["100 g getrocknete Hibiskusblüten (Sorrel)", "150 bis 200 g Zucker", "Frischer Ingwer oder Minzblätter", "Vanilleextrakt oder Orangenblütenwasser (nach Belieben)", "Oder ein fertiger Bissap-Sirup"],
              ["Die Blüten kurz in kaltem Wasser abspülen.", "In 2 Litern Wasser mit dem geriebenen Ingwer aufkochen und 15 Minuten neben dem Herd ziehen lassen.", "Abseihen und die Blüten gut ausdrücken.", "Noch warm süßen und mit Minze oder Vanille aromatisieren.", "Mindestens 2 Stunden kühlen und sehr kalt servieren."]),
    "okok": ["Süßes Okok", "Kamerun", "1 Std.", "6 Personen", "Das Gericht der Beti aus Zentral- und Südkamerun: fein geschnittene Okok-Blätter, in Palmnusssaft und Erdnusspaste gegart, mit Maniokstangen serviert.", ["500 g fein geschnittene Okok-Blätter (Eru)", "300 g Erdnusspaste", "1 Liter Palmnusssaft (oder 800 g Palmnusscreme)", "2 EL Zucker", "Maniokstangen (Bobolo) zum Servieren"], ["Die Okok-Blätter waschen und 10 Minuten in lauwarmem Wasser einweichen; abtropfen lassen.", "Den Palmnusssaft in einem großen Topf aufkochen.", "Die Erdnusspaste mit etwas heißem Saft verrühren, dazugeben und 15 Minuten unter Rühren kochen.", "Okok, Zucker und eine Prise Salz dazugeben; 30 Minuten bei schwacher Hitze unter Rühren garen, bis die Soße eindickt und das Öl aufsteigt.", "Heiß mit Maniokstangen servieren."]],
    "nkui": ["Nkui-Soße mit Maiscouscous", "Kamerun", "45 Min.", "6 Personen", "Die schleimige Soße der Bamiléké aus Westkamerun, aus Nkui-Rinde und gerösteten Gewürzen, mit Maiscouscous serviert.", ["50 g Nkui-Rinde", "Nkui-Gewürze: Djansang, weißer Pfeffer, Rondelle", "1 TL Steinsalz (Kanwa)", "2 Chilischoten", "1 Liter Wasser, Salz, 1 Brühwürfel", "Maiscouscous (Maismehl) zum Servieren"], ["Die Gewürze in einer trockenen Pfanne leicht rösten und mit den Chilis mahlen.", "Die Nkui-Rinde 15 Minuten in 1 Liter lauwarmem Wasser einweichen, dann zwischen den Händen reiben, um den schleimigen Saft zu lösen; die Rinde entfernen.", "Das in etwas Wasser gelöste und abgeseihte Kanwa, die gemahlenen Gewürze, Salz und Brühwürfel dazugeben.", "Unter Schlagen mit dem Schneebesen aufkochen, bis die Soße Fäden zieht.", "Weitere 5 Minuten kochen und heiß mit dem Maiscouscous servieren."]],
    "isombe": ["Isombe (Maniokblätter)", "Ruanda und Burundi", "1 Std. 15", "4 Personen", "Das Alltagsgericht in Ruanda und Burundi: gestampfte Maniokblätter, geschmort mit Aubergine, Lauch, Erdnusspaste und Palmöl.", ["200 g getrocknete gemahlene Maniokblätter (Isombe)", "1 Aubergine, 1 Zwiebel, 1 Stange Lauch", "2 EL Erdnusspaste", "100 ml Palmöl", "1 Räucher- oder Trockenfisch (nach Belieben)", "Salz, 1 Brühwürfel"], ["Die Blätter in 1,5 Liter Wasser 30 Minuten kochen (die Instantversion gart schneller: Packungsangabe beachten).", "Zwiebel, Lauch und Aubergine in Würfeln dazugeben; 20 Minuten garen.", "Die Erdnusspaste mit etwas Brühe verrühren und unterrühren.", "Den zerpflückten Fisch, Palmöl, Salz und Brühwürfel dazugeben.", "15 Minuten köcheln lassen, bis es eindickt. Mit Ugali, Reis oder Bananen servieren."]],
    "ugali-sukuma": ["Ugali und Sukuma Wiki", "Kenia", "40 Min.", "4 Personen", "Das Grundgericht Kenias: ein fester Brei aus weißem Maismehl mit Grünkohl, der mit Tomaten und Zwiebeln gebraten wird.", ["500 g weißes Maismehl", "1 Liter Wasser, Salz", "1 Bund Grünkohl oder Blattkohl (Sukuma)", "2 Tomaten, 1 Zwiebel", "2 EL Öl"], ["Das Salzwasser aufkochen und das Mehl unter Rühren einrieseln lassen.", "8 bis 10 Minuten kräftig mit einem Spatel bearbeiten, bis sich ein fester Teig vom Topf löst.", "Auf einem Teller zu einer Kuppel formen und abdecken.", "Sukuma: die Zwiebel im Öl anbraten, die Tomaten dazugeben und 5 Minuten garen.", "Den sehr fein geschnittenen Kohl dazugeben, salzen und 5 bis 7 Minuten garen: Er soll grün bleiben.", "Das Ugali mit dem Sukuma servieren, nach Belieben mit gegrilltem Fleisch (Nyama Choma)."]],
    "pilau": ["Rindfleisch-Pilau", "Tansania", "1 Std. 15", "6 Personen", "Der Festreis der Swahiliküste und Sansibars, in Fleischbrühe mit Kreuzkümmel, Zimt, Kardamom und Nelken gegart.", ["500 g Basmatireis", "700 g Rind- oder Ziegenfleisch in Würfeln", "2 Zwiebeln, 4 Knoblauchzehen, 1 Stück Ingwer", "Pilau-Gewürze: Kreuzkümmel, Zimt, Kardamom, Nelken, schwarzer Pfeffer", "1 Liter Brühe (oder 1 Brühwürfel)", "3 EL Öl"], ["Das Fleisch mit einer Zwiebel, Knoblauch, Ingwer und Salz 45 Minuten kochen; die Brühe aufbewahren.", "Die zweite Zwiebel in Ringen im Öl goldbraun braten.", "Die Gewürze 1 Minute mitrösten, dann das abgetropfte Fleisch dazugeben.", "Den gewaschenen Reis dazugeben und 2 Minuten rühren, damit er überzogen wird.", "750 ml heiße Brühe angießen, zudecken und bei sehr schwacher Hitze 20 Minuten garen.", "Mit Kachumbari servieren: fein gewürfelte Tomaten, Zwiebel und Chili."]],
    "matoke": ["Matoke", "Uganda", "1 Std.", "4 Personen", "Das Nationalgericht Ugandas: grüne Kochbananen, in einer gewürzten Tomatensoße geschmort, mit oder ohne Fleisch.", ["8 grüne Kochbananen", "500 g Rindfleisch in Würfeln (nach Belieben)", "2 Zwiebeln, 3 Tomaten", "2 Knoblauchzehen, Kurkuma, Currypulver", "2 EL Öl, Salz"], ["Die Bananen (mit eingeölten Händen) schälen und in Stücke schneiden; in Wasser legen.", "Zwiebel und Knoblauch im Öl anbraten, das Fleisch dazugeben und bräunen.", "Tomaten und Gewürze dazugeben; 10 Minuten garen.", "Die Bananen und so viel Wasser dazugeben, dass sie bedeckt sind; zugedeckt 30 Minuten garen.", "Einen Teil der Bananen zerdrücken, um die Soße zu binden, und heiß servieren."]],
    "doro-wat": ["Doro Wat mit Injera", "Äthiopien", "1 Std. 30", "6 Personen", "Der Hühnereintopf der äthiopischen Feste: viele weich geschmorte Zwiebeln, Berbere und Gewürzbutter, mit harten Eiern, auf Injera serviert.", ["1 Huhn in Stücken, ohne Haut", "1 kg rote Zwiebeln", "4 EL Berbere", "100 g Gewürzbutter (Niter Kibbeh) oder Butterschmalz", "6 hart gekochte Eier", "4 Knoblauchzehen, 1 Stück Ingwer, Saft einer Zitrone", "Injera (Teff-Fladen) oder Brot zum Servieren"], ["Das Huhn 20 Minuten mit Zitronensaft und Salz marinieren.", "Die gehackten Zwiebeln ohne Fett in einem Schmortopf 15 Minuten unter Rühren garen, bis sie braun werden.", "Butter, Knoblauch, Ingwer und Berbere dazugeben; 10 Minuten garen.", "Das Huhn und ein Glas Wasser dazugeben; zugedeckt 40 Minuten schmoren.", "Die eingeschnittenen Eier dazugeben und weitere 10 Minuten garen.", "Auf Injera servieren."]],
    "bobotie": ["Bobotie", "Südafrika", "1 Std. 10", "6 Personen", "Das südafrikanische Familiengericht: Hackfleisch mit mildem Curry, Chutney und Rosinen, unter einem Eierguss überbacken.", ["1 kg Rinderhackfleisch", "2 Zwiebeln, 2 Knoblauchzehen", "2 EL Currypulver, 1 TL Kurkuma", "2 Scheiben Brot, in 250 ml Milch eingeweicht", "3 EL Mangochutney und 50 g Rosinen", "2 Eier, einige Lorbeerblätter"], ["Den Ofen auf 180 °C vorheizen. Zwiebeln und Knoblauch in etwas Öl anbraten, Curry und Kurkuma dazugeben.", "Das Fleisch dazugeben und krümelig anbraten.", "Vom Herd nehmen und das ausgedrückte Brot (Milch aufbewahren), Chutney, Rosinen und Salz unterrühren.", "Die Masse in eine Auflaufform drücken.", "Die Eier mit der aufbewahrten Milch verquirlen, über das Fleisch gießen und die Lorbeerblätter hineinstecken.", "35 bis 40 Minuten backen, bis der Guss gestockt ist. Mit gelbem Reis servieren."]],
    "poulet-nyembwe": ["Huhn Nyembwe", "Gabun", "1 Std. 15", "6 Personen", "Das Nationalgericht Gabuns: Huhn, in Palmnusscreme (Nyembwe) geschmort, mit Reis oder Maniokstangen serviert.", ["1 Huhn in Stücken", "800 g Palmnusscreme (Nyembwe)", "2 Zwiebeln, 3 Knoblauchzehen", "2 Tomaten", "Chili, Salz, 1 Brühwürfel", "Reis oder Maniokstangen zum Servieren"], ["Das Huhn mit Knoblauch und Salz würzen und in einem Topf anbraten.", "Gehackte Zwiebeln und Tomaten dazugeben; 10 Minuten garen.", "Die Palmnusscreme und 250 ml Wasser dazugeben.", "40 Minuten bei schwacher Hitze garen und ab und zu umrühren, bis das Öl aufsteigt.", "Mit Salz und Chili abschmecken. Mit Reis oder Maniokstangen servieren."]],
    "waakye": ["Waakye", "Ghana", "1 Std. 15", "6 Personen", "Ghanas Frühstücksreis mit Bohnen, von Sorghumblättern braun gefärbt, mit Shito, Gari, Ei und gebratener Kochbanane serviert.", ["500 g Reis", "250 g Augenbohnen oder rote Bohnen", "6 getrocknete Sorghumblätter (oder 1 TL Natron)", "Salz", "Zum Servieren: Shito-Soße, Gari, Spaghetti, hart gekochtes Ei, gebratene Kochbanane"], ["Die Bohnen über Nacht in kaltem Wasser einweichen.", "40 Minuten mit den Sorghumblättern kochen, die die braune Farbe geben.", "Den gewaschenen Reis dazugeben, salzen und mit Wasser auffüllen, bis es 2 cm darübersteht.", "Zugedeckt bei schwacher Hitze 20 bis 25 Minuten garen.", "Die Blätter entfernen und mit Shito, Gari, Ei und gebratener Kochbanane servieren."]],
    "moi-moi": ["Moi Moi", "Nigeria", "1 Std. 30", "6 Personen", "Ein Pudding aus Augenbohnen, mit Paprika und Chili püriert, in Blättern oder Förmchen gedämpft, oft mit einem Stück Ei.", ["500 g Augenbohnen", "1 rote Paprikaschote, 2 Chilis, 1 Zwiebel", "100 ml Pflanzen- oder Palmöl", "2 Brühwürfel, Salz", "3 hart gekochte Eier (nach Belieben)", "Bananenblätter oder Förmchen"], ["Die Bohnen 1 Stunde einweichen, reiben, um die Haut zu entfernen, und abspülen.", "Mit Paprika, Chilis, Zwiebel und etwas Wasser zu einer glatten Paste pürieren.", "Öl, Brühwürfel, Salz und etwas lauwarmes Wasser dazugeben, bis ein flüssiger Teig entsteht.", "In gefettete Förmchen oder Bananenblätter füllen und ein Stück Ei hineinlegen.", "45 bis 50 Minuten dämpfen, bis es fest ist."]],
    "ayamase": ["Ayamase (grüne Soße mit Ofada-Reis)", "Nigeria", "1 Std. 30", "6 Personen", "Die Yoruba-Soße aus grüner Paprika und grünen Chilis, in gebleichtem Palmöl mit Iru, Fleisch und Eiern gebraten, mit Ofada-Reis serviert.", ["6 grüne Paprikaschoten und 4 grüne Chilis", "2 Zwiebeln", "250 ml Palmöl", "2 EL Iru (fermentierte Johannisbrotbohnen) und 1 EL gemahlene getrocknete Garnelen", "500 g Rindfleisch und Kutteln, 4 hart gekochte Eier", "2 Brühwürfel, Salz; Ofada-Reis zum Servieren"], ["Rindfleisch und Kutteln mit einer Zwiebel, Salz und einem Brühwürfel 45 Minuten kochen.", "Paprika und Chilis grob pürieren und 10 Minuten in einem Topf einkochen, um das Wasser zu entfernen.", "Das Palmöl zugedeckt 10 Minuten erhitzen, bis es hell wird (Fenster offen), etwas abkühlen lassen und darin die Zwiebelringe und das Iru braten.", "Die eingekochte Paprika dazugeben und 20 Minuten unter Rühren braten.", "Fleisch, Garnelen und Brühwürfel dazugeben; 10 Minuten köcheln lassen, dann die Eier dazugeben.", "Mit Ofada-Reis servieren."]],
    "amiwo": ["Amiwo (roter Maisbrei) mit Huhn", "Benin und Togo", "1 Std.", "6 Personen", "Der rote Festtagsmaisbrei aus Benin und Togo, in einer Tomatensoße mit gebratenem Huhn gegart.", ["400 g Maismehl (oder geröstetes Maismehl)", "1 Huhn in Stücken", "200 g Tomatenmark und 2 Tomaten", "2 Zwiebeln, 3 Knoblauchzehen, Chili", "4 EL Öl", "2 Brühwürfel, Salz"], ["Das Huhn würzen und im Öl braten; beiseitestellen.", "Im selben Öl Zwiebeln, Knoblauch, pürierte Tomaten und Tomatenmark 10 Minuten anbraten.", "1 Liter Wasser, Brühwürfel, Salz und Chili dazugeben; eine Schale Soße zum Servieren aufbewahren.", "Das Maismehl einrieseln lassen und kräftig mit einem Spatel rühren.", "15 Minuten bei schwacher Hitze bearbeiten, bis ein glatter roter Brei entsteht.", "Mit dem Huhn und der aufbewahrten Soße servieren."]],
    "thiakry": ["Thiakry", "Senegal", "30 Min.", "6 Personen", "Das kühle Dessert Senegals: gedämpfte Hirsekörner, mit gesüßtem Joghurt, Vanille und Muskat vermischt.", ["250 g Thiakry (Hirsecouscous)", "500 g Naturjoghurt oder Dickmilch", "200 ml gezuckerte Kondensmilch", "80 g Zucker, Vanille, Muskatnuss", "Rosinen (nach Belieben)"], ["Die Hirse 15 Minuten dämpfen (oder Packungsangabe beachten) und auflockern.", "Vollständig abkühlen lassen.", "Den Joghurt mit Kondensmilch, Zucker, Vanille und einer Prise Muskat verrühren.", "Mit der Hirse und den Rosinen vermischen.", "Mindestens 2 Stunden kühlen und gut gekühlt servieren."]],
    "ekwang": ["Ekwang", "Kamerun", "2 Std. 30", "6 Personen", "Eine Spezialität aus dem Littoral und dem Südwesten: geriebene Malanga, in Blätter gerollt und langsam in Palmnusssaft mit Räucherfisch und Garnelen gegart.", ["1,5 kg Malanga (Macabo)", "1 großes Bund Taro- oder Malangablätter (oder Spinat)", "1 Liter Palmnusssaft", "1 Räucherfisch und 100 g getrocknete Garnelen", "Chili, 2 Brühwürfel, Salz"], ["Die Malanga schälen und fein reiben; die Masse leicht salzen.", "Die Blätter waschen, je einen Löffel Masse daraufgeben und zu kleinen Zigarren rollen.", "Die Röllchen dicht in einen Topf schichten und mit Palmnusssaft und einem Glas Wasser bedecken.", "Den zerpflückten Fisch, die Garnelen, Chili und Brühwürfel dazugeben.", "1 Std. 30 bei schwacher Hitze garen, ohne zu rühren, dabei den Topf ab und zu schwenken, bis das Öl aufsteigt."]],
    "foutou-sauce-claire": ["Foutou mit klarer Soße", "Elfenbeinküste", "1 Std. 30", "6 Personen", "Gestampftes Kochbananen-Foutou mit der ivorischen klaren Soße: eine leichte Hühner- oder Fischbrühe mit Auberginen, Tomaten und Okra.", ["6 gerade reife Kochbananen und 300 g Maniok (oder Foutou-Pulver)", "1 Huhn in Stücken (oder 1 kg Fisch)", "3 afrikanische Auberginen, 3 Tomaten, 1 Zwiebel", "6 Okraschoten", "Chili, Ingwer, 1 Brühwürfel, Salz"], ["Das Huhn mit Zwiebel, Ingwer, Salz und 1,5 Liter Wasser 20 Minuten kochen.", "Auberginen, Tomaten und Chili ganz dazugeben; 15 Minuten kochen, dann herausnehmen und zerdrücken.", "Das Püree mit Okra und Brühwürfel zurück in die Brühe geben; 20 Minuten köcheln lassen.", "Foutou: Kochbanane und Maniok 20 Minuten kochen und zusammen zu einer glatten, elastischen Masse stampfen.", "Foutou-Kugeln formen und in der klaren Soße servieren."]],
    "riz-gras": ["Riz gras (fetter Reis)", "Burkina Faso und Mali", "1 Std. 15", "6 Personen", "Der Festtagsreis aus Burkina Faso und Mali, in einer reichhaltigen Tomatensoße mit Fleisch und Gemüse gegart.", ["600 g Reis", "800 g Rind- oder Hammelfleisch in Stücken", "200 g Tomatenmark und 3 Tomaten", "3 Zwiebeln, 2 Karotten, ½ Kohl", "150 ml Öl, 2 Brühwürfel, Salz, Chili"], ["Das Fleisch im Öl mit den Zwiebelringen anbraten.", "Pürierte Tomaten und Tomatenmark dazugeben; 10 Minuten garen.", "1,5 Liter Wasser angießen, Brühwürfel, Salz, Chili, Karotten und Kohl dazugeben; 30 Minuten kochen.", "Das Gemüse herausnehmen, den gewaschenen Reis dazugeben und mit Wasser auffüllen, bis es 1 cm darübersteht.", "Zudecken und 25 Minuten bei schwacher Hitze garen. Mit Fleisch und Gemüse servieren."]],
    "efo-riro": ["Efo Riro", "Nigeria", "1 Std.", "6 Personen", "Der Spinateintopf der Yoruba: Blattgemüse in einer Paprika-Chili-Basis mit Palmöl, Fleisch und Fisch.", ["1 kg Spinat (oder Amaranth)", "4 rote Paprikaschoten, 2 Chilis, 2 Zwiebeln", "150 ml Palmöl", "2 EL Iru und 2 EL gemahlene getrocknete Garnelen", "500 g gekochtes Rindfleisch und Kutteln, 1 Räucherfisch, 2 Brühwürfel"], ["Paprika, Chilis und eine Zwiebel grob pürieren; 10 Minuten einkochen.", "Das Palmöl erhitzen und die zweite Zwiebel in Ringen mit dem Iru anbraten.", "Die eingekochte Paprika dazugeben und 15 Minuten unter Rühren braten.", "Fleisch, Fisch, Garnelen und Brühwürfel dazugeben; 5 Minuten garen.", "Den gehackten Spinat unterrühren und nur 5 Minuten garen. Mit Eba, gestampftem Yam oder Reis servieren."]],
    "cachupa": ["Cachupa", "Kap Verde", "2 Std. 30", "8 Personen", "Das Nationalgericht Kap Verdes: Mais und Bohnen, lange mit Fleisch, Chorizo, Maniok, Süßkartoffel und Kohl geschmort.", ["500 g geschroteter Mais (Samp)", "300 g rote Bohnen oder Saubohnen", "800 g Schweine- und Hühnerfleisch, 1 Chorizo", "300 g Maniok und 1 Süßkartoffel", "½ Kohl, 2 Zwiebeln, 4 Knoblauchzehen, Lorbeer, Salz"], ["Mais und Bohnen über Nacht einweichen.", "1 Stunde mit dem Lorbeer kochen.", "Zwiebeln, Knoblauch und Fleisch in etwas Öl anbraten und mit der Chorizo in den Topf geben.", "Maniok, Süßkartoffel und Kohl in Stücken dazugeben; eine weitere Stunde bei schwacher Hitze garen.", "Salzen und heiß servieren; am nächsten Tag isst man die Cachupa gebraten mit einem Ei."]],
    "pikliz": ["Pikliz", "Haiti", "20 Min.", "10 Personen", "Das scharfe haitianische Relish: Kohl, Karotten und Scotch-Bonnet-Chilis in Essig, zu Griot und gebratenen Kochbananen.", ["½ Kohl, fein geschnitten", "2 Karotten in Streifen", "6 Scotch-Bonnet-Chilis", "500 ml weißer Essig und Saft einer Limette", "1 Zwiebel, 1 Paprikaschote, Nelken, Salz"], ["Kohl, Zwiebel und Paprika fein schneiden; die Karotten reiben.", "Die Chilis in dünne Ringe schneiden (mit Handschuhen).", "Das Gemüse mit Chilis, Salz und einigen Nelken mischen.", "In ein großes Glas drücken und mit Essig und Limettensaft bedecken.", "Verschließen und mindestens 24 Stunden im Kühlschrank ziehen lassen."]],
    "accras-morue": ["Stockfisch-Krapfen (Accras)", "Antillen", "1 Std.", "6 Personen", "Knusprige antillische Krapfen aus Salzkabeljau mit Chili, Knoblauch und Frühlingszwiebel: die klassische Vorspeise der Antillen.", ["300 g Salzkabeljau", "250 g Mehl und 1 Päckchen Backpulver", "1 Chili, 3 Knoblauchzehen, Petersilie, Frühlingszwiebel", "1 Zwiebel", "Öl zum Frittieren"], ["Den Kabeljau über Nacht in kaltem Wasser entsalzen (Wasser wechseln), dann 10 Minuten pochieren und zerpflücken.", "Mehl, Backpulver und etwa 300 ml Wasser zu einem dicken Teig verrühren.", "Kabeljau, gehackte Zwiebel, Knoblauch, Chili und Kräuter unterrühren; 30 Minuten ruhen lassen.", "Löffelweise Teig ins heiße Öl geben.", "Goldbraun frittieren, abtropfen lassen und heiß servieren."]],
    "brown-stew-chicken": ["Brown Stew Chicken", "Jamaika", "1 Std. 15", "6 Personen", "Jamaikanisches Huhn, in einer dunklen, süßen Soße mit Browning, Thymian, Scotch Bonnet und Paprika geschmort.", ["1,5 kg Huhn in Stücken", "2 EL Browning (Zuckercouleur) und 1 EL brauner Zucker", "1 Paprikaschote, 2 Tomaten, 1 Zwiebel, 3 Frühlingszwiebeln", "Thymian, 4 Knoblauchzehen, 1 Scotch Bonnet, Piment", "Reis mit Bohnen (Rice and Peas) zum Servieren"], ["Das Huhn über Nacht mit Knoblauch, Thymian, Frühlingszwiebeln, Piment, Salz und Browning marinieren.", "Das Huhn abtropfen lassen und im Öl gut anbraten.", "Zwiebel, Paprika, Tomaten und Marinade dazugeben; 5 Minuten garen.", "250 ml Wasser, den Zucker und die ganze Scotch Bonnet dazugeben; zugedeckt 35 Minuten schmoren.", "Die Soße eindicken lassen und mit Rice and Peas servieren."]],
    "pelau": ["Pelau", "Trinidad", "1 Std. 15", "6 Personen", "Das Festgericht Trinidads: in braunem Zucker karamellisiertes Huhn, mit Reis, Straucherbsen und Kokosmilch gegart.", ["1 kg Huhn in Stücken", "500 g Parboiled-Reis", "1 Dose Straucherbsen (Pigeon Peas)", "400 ml Kokosmilch", "3 EL brauner Zucker, Zwiebel, Knoblauch, Thymian, Chili, Karotte"], ["Das Huhn mit Knoblauch, Zwiebel, Thymian und Salz marinieren.", "Den Zucker im Öl zu dunklem Karamell schmelzen und das Huhn darin anbraten.", "Den gewaschenen Reis und die abgetropften Erbsen dazugeben; gut mischen.", "Kokosmilch und 500 ml Wasser angießen, Karotte und ganze Chili dazugeben.", "Zudecken und 30 Minuten bei schwacher Hitze garen, bis der Reis weich ist."]],
    "doubles": ["Doubles", "Trinidad", "2 Std.", "8 Personen", "Trinidads Straßensnack: zwei kleine frittierte Fladen (Bara), gefüllt mit Curry-Kichererbsen und scharfen Soßen.", ["500 g Mehl, 1 Päckchen Hefe, 1 TL Kurkuma", "2 Dosen Kichererbsen (Channa)", "2 EL Currypulver und 1 EL gemahlener Kreuzkümmel", "1 Zwiebel, 4 Knoblauchzehen, Chili", "Öl zum Frittieren; Tamarinden-Chutney und Chilisoße zum Servieren"], ["Bara: Mehl, Hefe, Kurkuma, Salz und 300 ml lauwarmes Wasser verrühren; 1 Stunde gehen lassen.", "Channa: Zwiebel und Knoblauch anbraten, Curry und Kreuzkümmel dazugeben, dann die Kichererbsen und etwas Wasser; 20 Minuten garen und leicht zerdrücken.", "Aus dem Teig kleine, sehr dünne Fladen formen.", "Sie einige Sekunden pro Seite im heißen Öl frittieren; sie gehen auf.", "Channa zwischen zwei Bara geben und Chutney und Chilisoße dazugeben."]],
    "sancocho": ["Sancocho", "Dominikanische Republik", "2 Std.", "8 Personen", "Der große dominikanische Festtagseintopf: verschiedene Fleischsorten mit Maniok, Yam, Kochbanane, Mais und Koriander.", ["1,5 kg gemischtes Fleisch (Huhn, Schwein, Rind)", "300 g Maniok und 300 g Yam", "2 grüne Kochbananen und 2 Maiskolben", "1 Zwiebel, 1 Paprikaschote, 4 Knoblauchzehen, Koriander, Oregano", "Saft von 2 Limetten, Salz; weißer Reis und Avocado zum Servieren"], ["Das Fleisch mit Limette, Knoblauch, Oregano und Salz marinieren.", "In einem großen Topf anbraten, dann Zwiebel und Paprika dazugeben.", "Mit 3 Liter Wasser bedecken und 45 Minuten kochen.", "Yam, Maniok, Kochbanane und Mais in Stücken dazugeben; 40 Minuten garen, bis die Brühe eindickt.", "Gehackten Koriander dazugeben und mit weißem Reis und Avocado servieren."]],
    "sanga": ["Sanga", "Kamerun", "1 Std. 15", "6 Personen", "Das Beti-Gericht der Maissaison: frischer Mais mit Blättern des Schwarzen Nachtschattens (Zom) und Palmnusssaft, leicht süß.", ["8 frische Maiskolben (oder 1 kg Maiskörner)", "1 kg Blätter des Schwarzen Nachtschattens (Zom) oder Spinat", "1 Liter Palmnusssaft", "2 EL Zucker", "Salz"], ["Die Maiskörner abstreifen und mit etwas Wasser grob pürieren.", "Die Blätter waschen, 10 Minuten kochen und gut ausdrücken, um die Bitterkeit zu entfernen.", "Den Palmnusssaft 15 Minuten unter Rühren kochen.", "Den pürierten Mais dazugeben und 15 Minuten bei schwacher Hitze unter Rühren garen.", "Blätter, Zucker und Salz dazugeben; weitere 15 Minuten garen. Heiß oder lauwarm servieren."]],
    "kedjenou-pintade": ["Perlhuhn-Kedjenou", "Elfenbeinküste", "1 Std. 30", "6 Personen", "Ivorisch geschmortes Perlhuhn: im eigenen Saft mit Tomaten, Auberginen und Chili gegart, in einem fest verschlossenen Topf, der geschüttelt wird.", ["1 Perlhuhn in Stücken", "4 Tomaten, 2 Auberginen, 2 Zwiebeln", "1 Stück Ingwer, 3 Knoblauchzehen", "Chili, Thymian, Lorbeer, Salz", "Attiéké oder Reis zum Servieren"], ["Das Perlhuhn mit dem geschnittenen Gemüse und dem zerdrückten Knoblauch und Ingwer in einen schweren Topf geben.", "Chili, Thymian, Lorbeer und Salz dazugeben; kein Wasser hinzufügen.", "Fest verschließen und 1 Stunde bei schwacher Hitze garen.", "Den Topf alle 10 Minuten schütteln, ohne ihn zu öffnen, damit nichts ansetzt.", "Mit Attiéké oder Reis servieren."]],
    "suya": ["Suya", "Nigeria", "45 Min. (+ 1 Std. Marinieren)", "6 Personen", "Die Straßenspieße Nordnigerias: dünn geschnittenes Rindfleisch in Yaji, einer Mischung aus gerösteten Erdnüssen und Gewürzen, über dem Feuer gegrillt.", ["1 kg Rindfleisch (Lende oder Hüfte) in dünnen Scheiben", "100 g gemahlene geröstete Erdnüsse (oder Kuli-Kuli-Pulver)", "2 TL Chilipulver, 1 TL Ingwer, 1 TL Paprika", "2 zerdrückte Brühwürfel, 1 TL Knoblauchpulver, Salz", "Rote Zwiebel, Tomate und Kohl zum Servieren"], ["Yaji: gemahlene Erdnüsse, Chili, Ingwer, Paprika, Brühwürfel, Knoblauch und Salz mischen.", "Die Fleischscheiben mit etwas Öl und dann mit dem Yaji einreiben.", "1 Stunde marinieren und auf Spieße stecken.", "10 bis 15 Minuten auf dem Grill oder im sehr heißen Ofen grillen und wenden.", "Mit Yaji bestreuen und mit roher roter Zwiebel, Tomate und Kohl servieren."]],
    "puff-puff": ["Puff Puff (Krapfen)", "Nigeria und Kamerun", "1 Std. 30", "8 Personen", "Die kleinen runden, lockeren Krapfen aus ganz West- und Zentralafrika, mit Muskat gewürzt.", ["500 g Mehl", "1 Päckchen Trockenhefe", "100 g Zucker", "½ TL Muskatnuss, 1 Prise Salz", "Öl zum Frittieren"], ["Mehl, Zucker, Hefe, Muskat und Salz mischen.", "Etwa 400 ml lauwarmes Wasser dazugeben und zu einem glatten, klebrigen Teig schlagen.", "Zudecken und 1 Stunde gehen lassen, bis er sich verdoppelt hat.", "Teigkugeln mit der Hand oder einem Löffel ins heiße Öl fallen lassen.", "Unter Wenden goldbraun frittieren; abtropfen lassen und servieren."]],
    "bouyon": ["Bouyon", "Haiti", "2 Std.", "8 Personen", "Die dicke Samstagssuppe Haitis: Fleisch, Wurzelgemüse, Blattgemüse und Mehlklößchen (Doumbrey).", ["1 kg Rind- oder Ziegenfleisch (mit Knochen)", "300 g Malanga, 300 g Yam, 2 grüne Bananen", "2 Karotten, 1 Chayote, 1 Bund Spinat oder Brunnenkresse", "200 g Mehl für die Klößchen (Doumbrey)", "Epis, Thymian, 1 Chili, 2 Brühwürfel, Salz, Limettensaft"], ["Das Fleisch mit Epis, Limette und Salz marinieren; 1 Stunde in 3 Liter Wasser kochen.", "Wurzelgemüse, Bananen, Karotten und Chayote in Stücken dazugeben.", "Doumbrey: Mehl, eine Prise Salz und etwas Wasser mischen und zu kleinen Röllchen formen.", "Klößchen, Spinat, Thymian, ganze Chili und Brühwürfel dazugeben; 30 Minuten garen.", "Etwas Gemüse zerdrücken, um die Suppe zu binden, und sehr heiß servieren."]],
    "callaloo": ["Callaloo", "Trinidad", "45 Min.", "6 Personen", "Trinidads grüne Suppe: Taroblätter (Dasheen) und Okra, in Kokosmilch gegart und glatt püriert.", ["500 g Taroblätter (Dasheen) oder Spinat", "8 Okraschoten", "400 ml Kokosmilch", "1 Zwiebel, 4 Knoblauchzehen, 3 Frühlingszwiebeln, Thymian, 1 Scotch Bonnet", "1 Krabbe oder 200 g Pökelschwein (nach Belieben), Salz"], ["Die Blätter waschen und hacken; die Okra in Scheiben schneiden.", "Zwiebel, Knoblauch und Frühlingszwiebeln in etwas Öl anbraten.", "Blätter, Okra, Kokosmilch, 250 ml Wasser, Thymian, Krabbe und ganze Chili dazugeben.", "Zugedeckt 30 Minuten garen.", "Die Chili entfernen, glatt pürieren und salzen. Mit Reis oder Foufou servieren."]],
    "ropa-vieja": ["Ropa Vieja", "Kuba", "2 Std. 30", "6 Personen", "Kubas Nationalgericht: lange gegartes, zerzupftes Rindfleisch, in Tomatensoße mit Paprika, Kreuzkümmel und Oregano geschmort.", ["1 kg Rinderflanke", "1 Dose gehackte Tomaten und 2 EL Tomatenmark", "2 Paprikaschoten, 1 Zwiebel, 4 Knoblauchzehen", "1 TL Kreuzkümmel, Oregano, Lorbeer", "Grüne Oliven (nach Belieben), Salz; Reis und schwarze Bohnen zum Servieren"], ["Das Rindfleisch mit Lorbeer und Salz 1 Std. 30 in Wasser kochen, bis es sehr zart ist.", "Etwas abkühlen lassen und mit zwei Gabeln zerzupfen; etwas Brühe aufbewahren.", "Zwiebel, Knoblauch und Paprikastreifen im Öl anbraten.", "Kreuzkümmel, Oregano, Tomaten, Tomatenmark und ein Glas Brühe dazugeben; 10 Minuten garen.", "Fleisch und Oliven dazugeben und 20 Minuten köcheln lassen. Mit Reis und schwarzen Bohnen servieren."]],
    "mofongo": ["Mofongo", "Puerto Rico", "45 Min.", "4 Personen", "Das puerto-ricanische Gericht: frittierte grüne Kochbananen, mit Knoblauch und knusprigem Schweinefleisch gestampft, mit Brühe serviert.", ["4 grüne Kochbananen", "6 Knoblauchzehen", "150 g frittierte Schweineschwarte oder Speck (Chicharrón)", "3 EL Olivenöl", "250 ml Hühnerbrühe, Salz; Öl zum Frittieren"], ["Die Kochbananen schälen, in 2 cm große Stücke schneiden und 8 Minuten bei mittlerer Hitze frittieren, ohne sie zu stark zu bräunen.", "Den Knoblauch mit Salz und Olivenöl im Mörser zerstoßen.", "Die heißen Kochbananen nach und nach dazugeben und mit dem knusprigen Schweinefleisch stampfen.", "Mit etwas Brühe beträufeln, damit das Mofongo saftig bleibt.", "Zu Kuppeln formen und mit der restlichen heißen Brühe servieren."]],
    "mbongo-porc": ["Mbongo mit Schweinefleisch", "Kamerun", "1 Std. 30", "6 Personen", "Die schwarze Soße der Bassa mit Schweinefleisch: geröstete Mbongo-Gewürze ergeben eine tiefe, rauchige Soße.", ["1,2 kg Schweinefleisch (Nacken oder Rippchen) in Stücken", "100 g Mbongo-Gewürze", "2 Tomaten, 1 Zwiebel, 4 Knoblauchzehen, 1 Stück Ingwer", "100 ml Palmöl", "Chili, 2 Brühwürfel, Salz; gekochte grüne Kochbananen zum Servieren"], ["Das Mbongo ohne Fett rösten, bis es richtig schwarz ist, dann mahlen.", "Tomaten, Zwiebel, Knoblauch, Ingwer und Mbongo mit etwas Wasser pürieren.", "Das Schweinefleisch 10 Minuten im Palmöl anbraten.", "Das Püree, 500 ml Wasser, Chili und Brühwürfel dazugeben; 50 Minuten bei schwacher Hitze garen.", "Mit Salz abschmecken und mit gekochten grünen Kochbananen servieren."]],
    "thieb-yapp": ["Thieb Yapp (Reis mit Fleisch)", "Senegal", "1 Std. 30", "6 Personen", "Der Fleisch-Vetter des Thieboudienne: Lamm oder Rind, weich geschmorte Zwiebeln und Bruchreis, in der Soße gegart.", ["600 g Bruchreis", "1 kg Lamm- oder Rindfleisch in Stücken", "4 Zwiebeln, 4 Knoblauchzehen", "2 EL Senf und 2 EL Tomatenmark", "150 ml Öl, Pfeffer, 2 Brühwürfel, Salz, 1 Chili"], ["Das Fleisch mit Knoblauch, Senf, Pfeffer und Salz marinieren.", "Im Öl anbraten, dann die Zwiebelringe dazugeben und weich schmoren.", "Tomatenmark, 1,5 Liter Wasser, Brühwürfel und Chili dazugeben; 45 Minuten garen.", "Das Fleisch herausnehmen, den Reis waschen, 15 Minuten dämpfen und in die Soße geben.", "Zugedeckt 20 Minuten bei schwacher Hitze garen und mit Fleisch und Zwiebeln servieren."]],
    "domoda": ["Domoda", "Gambia", "1 Std. 30", "6 Personen", "Gambias Nationalgericht: Fleischeintopf mit Erdnusspaste und Kürbis oder Süßkartoffel, auf Reis serviert.", ["1 kg Rind- oder Hühnerfleisch in Stücken", "250 g Erdnusspaste", "500 g Kürbis oder Süßkartoffel", "2 Zwiebeln, 3 Tomaten, 2 EL Tomatenmark", "Chili, 2 Brühwürfel, Saft einer Zitrone, Salz; Reis zum Servieren"], ["Das Fleisch mit den Zwiebeln in etwas Öl anbraten.", "Pürierte Tomaten und Tomatenmark dazugeben; 10 Minuten garen.", "Die Erdnusspaste in 1 Liter heißem Wasser verrühren und mit Brühwürfeln und Chili dazugeben.", "Den Kürbis in Würfeln dazugeben und 45 Minuten bei schwacher Hitze unter Rühren garen.", "Zitronensaft dazugeben, mit Salz abschmecken und auf Reis servieren."]],
    "fufu-light-soup": ["Fufu mit Light Soup", "Ghana", "1 Std. 30", "6 Personen", "Ghanaisches Fufu in Light Soup, einer Brühe aus Tomate, Aubergine und Chili mit Huhn oder Ziege.", ["1 Huhn oder 1 kg Ziegenfleisch in Stücken", "4 Tomaten, 2 Auberginen, 2 Zwiebeln, 1 Stück Ingwer", "2 Scotch-Bonnet-Chilis", "2 Brühwürfel, Salz", "Fufu (Pulvermischung aus Kochbanane und Maniok) zum Servieren"], ["Das Fleisch mit einer Zwiebel, Ingwer, Salz und 500 ml Wasser 15 Minuten kochen.", "Tomaten, Auberginen, die zweite Zwiebel, die ganzen Chilis und 1,5 Liter Wasser dazugeben; 15 Minuten kochen.", "Das Gemüse herausnehmen, pürieren und durch ein Sieb zurück in die Suppe streichen.", "Die Brühwürfel dazugeben und 30 Minuten köcheln lassen.", "Das Fufu nach Packungsangabe zubereiten, zu Kugeln formen und in der Suppe servieren."]],
    "ofe-onugbu": ["Ofe Onugbu (Bitterblattsuppe)", "Nigeria", "1 Std. 30", "6 Personen", "Die Igbo-Suppe mit Bitterblättern (Onugbu), mit Cocoyam und Palmöl gebunden, mit Fleisch, Stockfisch und Garnelen.", ["2 Handvoll gewaschene Bitterblätter (frisch, getrocknet oder tiefgekühlt)", "300 g Cocoyam (oder Malanga)", "150 ml Palmöl", "1 kg gemischtes Fleisch, 1 Stück Stockfisch", "2 EL gemahlene getrocknete Garnelen, Chili, 2 Brühwürfel, Salz"], ["Das Fleisch und den eingeweichten Stockfisch mit Salz und Brühwürfeln 40 Minuten kochen.", "Den Cocoyam 20 Minuten kochen, schälen und zu einer Paste stampfen.", "Palmöl, Garnelen, Chili und kleine Stücke Cocoyam-Paste in die Brühe geben.", "15 Minuten garen, bis die Suppe eindickt.", "Die Bitterblätter dazugeben, 5 Minuten garen und mit Fufu oder Eba servieren."]],
    "saka-saka-poisson": ["Saka-Saka mit Salzfisch", "Kongo", "1 Std. 30", "6 Personen", "Gestampfte Maniokblätter auf kongolesische Art, lange in Palmöl mit Salzfisch und Auberginen gegart.", ["1 kg gestampfte Maniokblätter (tiefgekühlt)", "300 g Salzfisch (Kabeljau oder Makayabu)", "150 ml Palmöl", "2 afrikanische Auberginen, 1 Paprikaschote", "2 Zwiebeln, 4 Knoblauchzehen, Chili, Salz"], ["Den Fisch über Nacht in kaltem Wasser entsalzen, dann zerpflücken.", "Die Maniokblätter in 1,5 Liter Wasser 45 Minuten kochen.", "Gehackte Auberginen, Paprika, Zwiebeln und Knoblauch dazugeben; 20 Minuten garen.", "Salzfisch, Palmöl und Chili dazugeben.", "20 Minuten köcheln lassen, bis das Wasser verdampft ist. Mit Foufou oder Chikwangue servieren."]],
    "mandazi": ["Mandazi", "Kenia und Tansania", "1 Std. 30", "8 Personen", "Krapfen der Swahiliküste mit Kokosmilch und Kardamom, zum Eintauchen in Chai.", ["500 g Mehl", "250 ml Kokosmilch", "80 g Zucker und 1 Päckchen Trockenhefe", "1 TL gemahlener Kardamom", "1 Prise Salz; Öl zum Frittieren"], ["Mehl, Zucker, Hefe, Kardamom und Salz mischen.", "Die lauwarme Kokosmilch dazugeben und 5 Minuten zu einem weichen Teig kneten.", "Zudecken und 1 Stunde gehen lassen.", "Den Teig 1 cm dick ausrollen und in Dreiecke schneiden.", "Im heißen Öl frittieren, bis sie aufgehen und goldbraun sind; abtropfen lassen."]],
    "blaff-poisson": ["Fisch-Blaff", "Martinique", "40 Min.", "4 Personen", "Antillischer Fisch, in Limette mariniert und in einem Sud mit Thymian, Chili und Knoblauch pochiert.", ["1 kg Fisch (Schnapper, Dorade oder Wolfsbarsch) in Scheiben", "Saft von 4 Limetten", "1 Chili, 4 Knoblauchzehen, 2 Frühlingszwiebeln", "1 Zwiebel, Thymian, Petersilie, 2 Nelken", "Salz, Pfeffer; weißer Reis zum Servieren"], ["Den Fisch 1 Stunde mit dem Saft von 3 Limetten, zerdrücktem Knoblauch, Chili, Salz und Pfeffer marinieren.", "1 Liter Wasser mit Zwiebel, Frühlingszwiebeln, Thymian, Petersilie und Nelken aufkochen.", "Fisch und Marinade in den siedenden Sud geben.", "8 bis 10 Minuten leise sieden lassen.", "Den Saft der letzten Limette dazugeben und mit dem Sud und weißem Reis servieren."]],
    "bake-and-shark": ["Bake and Shark", "Trinidad", "1 Std. 15", "6 Personen", "Trinidads Strandsandwich: marinierter, frittierter Fisch in einem frittierten Brot (Bake), mit Salat und Soßen.", ["1 kg Haifilet oder fester weißer Fisch", "Saft von 2 Limetten, 4 Knoblauchzehen, Thymian, Chili", "Bake-Teig: 400 g Mehl, 1 Päckchen Backpulver, 1 EL Zucker, Salz", "100 g Mehl zum Wenden des Fisches", "Öl zum Frittieren; Salat, Tomate, Knoblauch- und Tamarindensoße"], ["Den Fisch 1 Stunde mit Limette, Knoblauch, Thymian, Chili und Salz marinieren.", "Bake: Mehl, Backpulver, Zucker, Salz und etwa 250 ml Wasser verrühren; 30 Minuten ruhen lassen.", "Fladen formen und frittieren, bis sie aufgehen.", "Den Fisch in Mehl wenden und 4 bis 5 Minuten frittieren.", "Die Bakes aufschneiden und mit Fisch, Salat und Soßen füllen."]],
    "moro-guandules": ["Moro de Guandules", "Dominikanische Republik", "45 Min.", "6 Personen", "Dominikanischer Reis mit Straucherbsen, mit Sofrito, Kokosmilch und Koriander gegart.", ["500 g Reis", "1 Dose Straucherbsen (Guandules)", "200 ml Kokosmilch", "1 Zwiebel, 1 Paprikaschote, 3 Knoblauchzehen, Koriander", "2 EL Tomatenmark, Oregano, 1 Brühwürfel, Salz"], ["Zwiebel, Paprika, Knoblauch und Koriander in etwas Öl anbraten.", "Tomatenmark, Oregano und die abgetropften Erbsen dazugeben; 5 Minuten garen.", "Kokosmilch, 600 ml Wasser, Brühwürfel und Salz dazugeben; aufkochen.", "Den gewaschenen Reis dazugeben und offen garen, bis die Flüssigkeit fast aufgesogen ist.", "Zudecken und 15 Minuten bei sehr schwacher Hitze fertig garen."]],
    "placali-kope": ["Placali mit Kopè-Soße", "Elfenbeinküste", "1 Std.", "6 Personen", "Fermentierte Maniokpaste (Placali) mit Kopè: einer Okrasoße mit Palmöl, Räucherfisch und Krabben.", ["500 g Placali (fermentierte Maniokpaste)", "500 g frische Okra", "150 ml Palmöl", "1 Räucherfisch und 2 Krabben", "Chili, 1 Zwiebel, 1 Brühwürfel, Salz"], ["Die Okra fein schneiden oder grob pürieren.", "1 Liter Wasser mit Zwiebel, zerpflücktem Fisch, Krabben, Chili und Brühwürfel erhitzen; 15 Minuten kochen.", "Okra und Palmöl dazugeben; 15 Minuten unter Schlagen kochen, bis die Soße Fäden zieht.", "Placali: die Paste in 750 ml Wasser verrühren und 10 bis 15 Minuten unter ständigem Rühren garen, bis sie glatt und durchscheinend ist.", "Das Placali in tiefen Tellern mit der Kopè-Soße servieren."]],
    "red-red": ["Red Red", "Ghana", "1 Std. 15", "4 Personen", "Augenbohnen, in Palmöl und Tomate geschmort, mit gebratener reifer Kochbanane: Ghanas rotes… und rotes Gericht.", ["400 g Augenbohnen", "150 ml Palmöl", "3 Tomaten, 1 Zwiebel, 1 Chili, 1 Stück Ingwer", "4 reife Kochbananen", "Gari zum Servieren, Salz, 1 Brühwürfel"], ["Die Bohnen 2 Stunden einweichen, dann 45 Minuten kochen; abgießen.", "Das Palmöl erhitzen und Zwiebel, Ingwer und Chili anbraten.", "Pürierte Tomaten, Brühwürfel und Salz dazugeben; 10 Minuten garen.", "Bohnen und etwas Wasser dazugeben; 10 Minuten köcheln lassen und leicht zerdrücken.", "Die Kochbanane in Scheiben braten und mit den Bohnen servieren, mit Gari bestreut."]],
    "colombo-poulet": ["Hähnchen-Colombo", "Guadeloupe und Martinique", "1 Std. 15", "6 Personen", "Das Curry der Französischen Antillen: Huhn, mit Colombo-Pulver, Kartoffeln, Aubergine und Chayote geschmort.", ["1 Huhn in Stücken", "3 EL Colombo-Pulver", "3 Kartoffeln, 1 Aubergine, 1 Chayote", "2 Zwiebeln, 4 Knoblauchzehen, 1 Chili, Thymian", "Saft von 2 Limetten; weißer Reis zum Servieren"], ["Das Huhn 1 Stunde mit Limette, Knoblauch, Salz und einem Löffel Colombo marinieren.", "Im Öl mit den Zwiebeln anbraten.", "Den restlichen Colombo, Thymian und die ganze Chili dazugeben; 2 Minuten rühren.", "Das Gemüse in Stücken und Wasser zum Bedecken dazugeben; zugedeckt 40 Minuten garen.", "Zum Schluss etwas Limettensaft dazugeben und mit weißem Reis servieren."]],
    "kwacoco-bible": ["Kwacoco Bible", "Kamerun", "2 Std.", "6 Personen", "Ein Päckchen aus dem Südwesten: geriebene Malanga mit Räucherfisch, Gewürzen und Palmöl, in Bananenblättern gegart.", ["1 kg Malanga (Macabo)", "1 Räucherfisch und 50 g getrocknete Garnelen", "Bananenblätter", "100 ml Palmöl", "Chili, 1 Zwiebel, 1 Brühwürfel, Salz"], ["Die Malanga schälen und fein reiben.", "Zerpflückten Fisch, gemahlene Garnelen, gehackte Zwiebel, Chili, Brühwürfel, Salz und Palmöl dazugeben; gut mischen.", "Die Masse auf über der Flamme erweichte Bananenblätter verteilen.", "Die Päckchen falten und zubinden.", "1 Std. 30 dämpfen. Mit einer Chilisoße oder einem Eintopf servieren."]],
    "sauce-feuille-patate": ["Süßkartoffelblätter-Soße", "Guinea", "1 Std. 15", "6 Personen", "Die guineische Soße aus gestampften Süßkartoffelblättern, in Palmöl mit Fleisch und Räucherfisch gegart, auf Reis serviert.", ["1 kg Süßkartoffelblätter (frisch oder tiefgekühlt)", "200 ml Palmöl", "600 g Rindfleisch in Stücken", "1 Räucherfisch, 2 EL getrocknete Garnelen", "2 Zwiebeln, Chili, 2 Brühwürfel, Salz; Reis zum Servieren"], ["Die Blätter waschen und stampfen oder sehr fein hacken.", "Das Fleisch mit einer Zwiebel, Salz und 1 Liter Wasser 40 Minuten kochen.", "Blätter, zerpflückten Fisch und Garnelen dazugeben; 20 Minuten garen.", "Palmöl, die zweite gehackte Zwiebel, Chili und Brühwürfel dazugeben.", "20 Minuten köcheln lassen, bis das Öl aufsteigt. Auf weißem Reis servieren."]],
    "chakchouka": ["Shakshuka", "Tunesien", "40 Min.", "4 Personen", "Pochierte Eier in einer Tomaten-Paprika-Soße mit Kreuzkümmel und Harissa, zum Tunken mit Brot.", ["6 Tomaten (oder 1 Dose gehackte Tomaten)", "3 Paprikaschoten, 1 Zwiebel, 3 Knoblauchzehen", "6 Eier", "1 TL Kreuzkümmel, 1 TL Paprikapulver", "1 TL Harissa, Olivenöl, Salz; Brot zum Servieren"], ["Zwiebel und Paprikastreifen 10 Minuten im Olivenöl anbraten.", "Knoblauch, Kreuzkümmel, Paprika und Harissa dazugeben; 1 Minute garen.", "Tomaten und Salz dazugeben; 15 Minuten köcheln lassen.", "Mulden in die Soße drücken und die Eier hineinschlagen.", "Zudecken und 6 bis 8 Minuten garen, bis das Eiweiß gestockt ist. Mit Brot servieren."]],
    "diri-ak-pwa": ["Diri ak Pwa (Reis mit roten Bohnen)", "Haiti", "1 Std. 15", "6 Personen", "Haitis Alltagsreis, in der Brühe roter Bohnen mit Epis, Nelken und einer ganzen Chili gegart.", ["500 g Reis", "250 g getrocknete rote Kidneybohnen", "2 EL Epis (haitianische Würze)", "3 Nelken, Thymian, 1 Scotch Bonnet", "2 EL Öl oder Butter, Salz"], ["Die Bohnen 1 Stunde in 1,5 Liter Wasser kochen; die Brühe aufbewahren.", "Das Epis im Öl anbraten, die abgetropften Bohnen dazugeben und 3 Minuten anbraten.", "1 Liter Brühe, Nelken, Thymian, Salz und die ganze Chili dazugeben; aufkochen.", "Den gewaschenen Reis dazugeben und offen garen, bis die Flüssigkeit aufgesogen ist.", "Zudecken und 15 Minuten bei sehr schwacher Hitze fertig garen. Die Chili entfernen und servieren."]],
    "festival": ["Festival", "Jamaika", "40 Min.", "6 Personen", "Jamaikanische süße Maismehlkrapfen, goldbraun frittiert, zu gebratenem Fisch und Jerk Chicken.", ["250 g Weizenmehl", "150 g feines Maismehl", "3 EL Zucker und 1 Päckchen Backpulver", "1 TL Vanille, 1 Prise Salz", "Öl zum Frittieren"], ["Mehl, Maismehl, Zucker, Backpulver und Salz mischen.", "Vanille und etwa 200 ml Wasser dazugeben, bis ein weicher Teig entsteht.", "2 Minuten kneten und 15 Minuten ruhen lassen.", "Zu 10 cm langen Röllchen formen.", "5 Minuten im heißen Öl goldbraun frittieren."]],
    "attieke-aubergine": ["Attiéké mit Auberginensoße", "Elfenbeinküste", "1 Std.", "6 Personen", "Attiéké mit einer milden, duftenden Soße aus zerdrückten Auberginen, Tomate und Fisch.", ["1 kg Attiéké", "6 afrikanische Auberginen (oder 2 große Auberginen)", "800 g Fisch (oder 1 Räucherfisch)", "3 Tomaten, 2 Zwiebeln, 2 Knoblauchzehen", "4 EL Öl, Chili, 1 Brühwürfel, Salz"], ["Die geschälten Auberginen 15 Minuten kochen und zerdrücken.", "Zwiebeln und Knoblauch im Öl anbraten, die pürierten Tomaten dazugeben; 10 Minuten garen.", "Die zerdrückten Auberginen, 300 ml Wasser, Chili, Brühwürfel und Salz dazugeben; 10 Minuten garen.", "Den Fisch dazugeben und 15 Minuten bei schwacher Hitze garen.", "Das Attiéké 5 Minuten dämpfen und mit der Soße servieren."]],
    "run-down": ["Run Down", "Jamaika", "45 Min.", "4 Personen", "Fisch (Makrele oder Kabeljau), in eingekochter Kokosmilch mit Tomaten, Zwiebeln, Thymian und Chili geschmort.", ["600 g gesalzene Makrele oder frischer Fisch", "800 ml Kokosmilch", "2 Tomaten, 1 Zwiebel, 3 Frühlingszwiebeln, 3 Knoblauchzehen", "Thymian, 1 Scotch Bonnet, Piment", "Grüne Bananen oder Dumplings zum Servieren"], ["Gesalzenen Fisch über Nacht wässern und zerpflücken.", "Die Kokosmilch 15 Minuten einkochen, bis sich das Öl absetzt.", "Zwiebel, Knoblauch, Frühlingszwiebeln, Tomaten, Thymian und die ganze Chili dazugeben; 5 Minuten garen.", "Den Fisch dazugeben und 10 Minuten bei schwacher Hitze garen.", "Mit gekochten grünen Bananen oder Dumplings servieren."]],
    "cochinita-pibil": ["Cochinita pibil", "Mexiko", "4 h (+ 1 Nacht Marinieren)", "8 Personen", "Gezupftes Schweinefleisch aus Yucatán: in Achiote und Zitrussaft mariniert und langsam in Bananenblättern gegart, bis es zerfällt.", ["2 kg Schweineschulter in großen Stücken", "100 g Achiote-Paste (Annatto)", "Saft von 4 Orangen und 2 Limetten, 4 Knoblauchzehen, je 1 Teelöffel Oregano und Kreuzkümmel, Salz", "Bananenblätter", "Maistortillas, in Limettensaft eingelegte rote Zwiebel und Habanero-Chili zum Servieren"], ["Die Achiote-Paste im Orangen- und Limettensaft mit dem zerdrückten Knoblauch, Oregano, Kreuzkümmel und Salz auflösen.", "Das Fleisch mit der Marinade bedecken und über Nacht in den Kühlschrank stellen.", "Eine Form mit über der Flamme geschmeidig gemachten Bananenblättern auslegen, das Fleisch mit der Marinade hineingeben und die Blätter darüber schlagen.", "Mit Alufolie abdecken und bei 160 °C 4 Stunden im Ofen garen, bis sich das Fleisch mit der Gabel zerzupfen lässt.", "Das Fleisch im eigenen Saft zerzupfen und in warmen Tortillas mit der eingelegten Zwiebel und Chili servieren."]],
    "tamales": ["Hähnchen-Tamales", "Mexiko", "2 h 30", "6 Personen", "Mexikos Päckchen aus Maisteig, gefüllt mit Hähnchen in scharfer Soße und in Maisblättern gedämpft.", ["500 g Maismehl für Tamales (Masa)", "20 getrocknete Maisblätter", "500 g gegartes, gezupftes Hähnchen", "1 Dose Chipotle-Chilis in Adobo-Soße (oder Salsa verde)", "150 g Schmalz oder Pflanzenfett, 500 ml Hühnerbrühe, 1 Teelöffel Backpulver, Salz"], ["Die Maisblätter 30 Minuten in heißem Wasser einweichen.", "Das Fett hell aufschlagen, dann Masa, Backpulver, Salz und nach und nach die Brühe zugeben, bis ein weicher Teig entsteht, von dem eine kleine Kugel im Wasser schwimmt.", "Das Hähnchen mit den gehackten Chipotle-Chilis und etwas Soße mischen.", "2 Löffel Teig auf jedes Blatt streichen, einen Löffel Hähnchen daraufgeben, die Seiten und dann das untere Ende einschlagen.", "Stehend 1 h 15 dämpfen, bis sich der Teig sauber vom Blatt löst."]],
    "gallo-pinto": ["Gallo pinto", "Costa Rica und Nicaragua", "30 min", "4 Personen", "Das Frühstück Mittelamerikas: Reis vom Vortag, angebraten mit schwarzen Bohnen, Zwiebel, Paprika und Koriander.", ["2 Tassen gekochte schwarze Bohnen mit etwas Kochflüssigkeit", "3 Tassen weißer Reis vom Vortag", "1 Zwiebel und 1 rote Paprika, gehackt, 2 Knoblauchzehen", "1 Bund Koriander", "2 Esslöffel Öl, Salz; Lizano- oder Worcestershiresoße nach Geschmack"], ["Zwiebel, Paprika und Knoblauch 5 Minuten im Öl anbraten.", "Die Bohnen mit ihrer Flüssigkeit zugeben und 3 Minuten einkochen lassen.", "Den Reis zugeben und vorsichtig mischen, bis er die Farbe der Bohnen annimmt.", "Mit Salz und einem Spritzer Lizano-Soße würzen.", "Mit Koriander bestreuen und mit Eiern, gebratener reifer Kochbanane und Sauerrahm servieren."]],
    "mangu": ["Mangú", "Dominikanische Republik", "40 min", "4 Personen", "Dominikanisches Püree aus grüner Kochbanane mit Essig-Zwiebeln, serviert mit den „drei Schlägen“: Salami, gebratener Käse und Ei.", ["4 grüne Kochbananen", "2 rote Zwiebeln in Ringen", "3 Esslöffel Butter", "Essig, Öl, Salz", "Bratkäse, Salami und Eier zum Servieren"], ["Die Kochbananen schälen, in Stücke schneiden und 20 Minuten in Salzwasser kochen.", "Die Zwiebeln in etwas Öl andünsten, einen Schuss Essig und Salz zugeben.", "Die Kochbananen mit der Butter und etwas kaltem Kochwasser zu einem glatten Püree stampfen.", "Salami- und Käsescheiben braten und die Eier zubereiten.", "Das Püree mit den Zwiebeln bedeckt servieren, dazu Salami, Käse und Eier."]],
    "patacones": ["Patacones", "Kolumbien", "30 min", "4 Personen", "Zweimal frittierte, knusprige Taler aus grüner Kochbanane, mit Hogao (Tomaten-Frühlingszwiebel-Soße) und Avocado.", ["3 grüne Kochbananen", "Öl zum Frittieren", "Salz und 1 zerdrückte Knoblauchzehe in einer Schüssel Wasser", "Hogao: 2 Tomaten, 4 Frühlingszwiebeln, Öl, Salz", "1 Avocado"], ["Die Kochbananen schälen und in 4 cm lange Stücke schneiden.", "5 Minuten in mittelheißem Öl frittieren, ohne sie zu bräunen, dann abtropfen lassen.", "Zwischen zwei Brettern oder mit dem Boden eines Glases flach drücken und in das gesalzene Knoblauchwasser tauchen.", "In sehr heißem Öl erneut frittieren, bis sie goldbraun und knusprig sind; salzen.", "Hogao: die gehackten Tomaten und Frühlingszwiebeln 10 Minuten im Öl schmoren. Mit zerdrückter Avocado servieren."]],
    "bolon-verde": ["Bolón de verde", "Ecuador", "40 min", "4 Personen", "Kugeln aus grüner Kochbanane von Ecuadors Küste, mit Käse und knusprigem Schweinefleisch gestampft und in der Pfanne gebräunt.", ["4 grüne Kochbananen", "150 g Grillkäse oder Mozzarella, gewürfelt", "150 g Chicharrón (frittiertes Schweinefleisch) oder Speck", "2 Esslöffel Butter oder Schmalz", "½ Teelöffel Achiote (Annatto), Salz"], ["Die Kochbananen in Stücke schneiden und 20 Minuten in Salzwasser kochen.", "Das Schweinefleisch in kleinen Stücken anbraten und das Fett aufbewahren.", "Die heißen Kochbananen mit Butter, Achiote und etwas Fett stampfen.", "Käse und Fleisch untermischen und orangengroße Kugeln formen.", "In etwas Öl in der Pfanne bräunen. Zum Frühstück mit einem Ei und Kaffee servieren."]],
    "sopa-quinoa": ["Quinoasuppe", "Peru und Bolivien", "45 min", "6 Personen", "Die Suppe der Anden: Quinoa, Kartoffeln und Gemüse in einer mit Ají gewürzten Brühe, mit Frischkäse.", ["200 g Quinoa, gründlich gespült", "3 Kartoffeln und 2 Karotten, gewürfelt", "1 Zwiebel, 2 Knoblauchzehen, 1 Esslöffel Ají-Paste (oder Paprikapulver)", "2 Liter Hühner- oder Gemüsebrühe, 1 Tasse Erbsen oder Saubohnen", "Koriander oder Petersilie, gewürfelter Frischkäse, Salz"], ["Zwiebel, Knoblauch und Ají 5 Minuten in etwas Öl anbraten.", "Brühe und Quinoa zugeben; 15 Minuten kochen.", "Kartoffeln und Karotten zugeben; 15 Minuten kochen.", "Erbsen oder Saubohnen zugeben, weitere 5 Minuten kochen und salzen.", "Mit gehacktem Koriander und einigen Würfeln Frischkäse servieren."]],
    "ful-medames": ["Ful medames", "Ägypten", "20 min", "4 Personen", "Ägyptens Frühstück: langsam gegarte Saubohnen, zerdrückt mit Knoblauch, Kreuzkümmel, Zitrone und Olivenöl.", ["2 Dosen Saubohnen (Ful) à 400 g", "2 Knoblauchzehen, 1 Teelöffel Kreuzkümmel, Salz", "Saft von 1 Zitrone", "4 Esslöffel Olivenöl", "Tomate, Petersilie, Zwiebel, hartgekochte Eier und Pitabrot zum Servieren"], ["Die Bohnen mit ihrer Flüssigkeit 10 Minuten bei schwacher Hitze erwärmen.", "Den Knoblauch mit Salz und Kreuzkümmel zerdrücken.", "Einen Teil der Bohnen grob zerdrücken, Knoblauch und Zitronensaft zugeben, bei Bedarf etwas heißes Wasser.", "In eine flache Schale geben und großzügig mit Olivenöl beträufeln.", "Mit gehackter Tomate und Petersilie, Zwiebel und Ei garnieren; mit warmem Pitabrot servieren."]],
    "chorba-frik": ["Chorba frik", "Algerien", "1 h 15", "6 Personen", "Algeriens Ramadan-Suppe: Lamm, Tomate und geschroteter grüner Weizen, mit Koriander und Minze gewürzt.", ["500 g Lammfleisch in kleinen Stücken", "100 g Frik (geschroteter grüner Weizen)", "1 Dose Kichererbsen", "2 geriebene Tomaten und 1 Esslöffel Tomatenmark", "1 Zwiebel, 1 Bund Koriander, getrocknete Minze, Zimt, Paprikapulver, Salz, Pfeffer"], ["Lamm und gehackte Zwiebel in etwas Öl mit Zimt, Paprika, Salz und Pfeffer anbraten.", "Tomaten, Tomatenmark, die Hälfte des gehackten Korianders und 2 Liter Wasser zugeben; 40 Minuten kochen.", "Die abgetropften Kichererbsen zugeben und den Frik einrieseln lassen; 20 Minuten kochen und gelegentlich umrühren.", "Den restlichen Koriander und eine Prise getrocknete Minze zugeben.", "Mit einem Zitronenschnitz, Datteln und Brot servieren."]],
    "misir-wat": ["Misir wat", "Äthiopien", "45 min", "4 Personen", "Äthiopischer Eintopf aus roten Linsen mit Berbere, rot und scharf, auf Injera serviert.", ["250 g rote Linsen", "2 rote Zwiebeln, sehr fein gehackt", "2 Esslöffel Berbere (oder Chilipulver mit Paprika und Gewürzen)", "3 Knoblauchzehen", "1 Stück Ingwer, 4 Esslöffel Öl oder geklärte Butter, Salz"], ["Die Zwiebeln ohne Fett bei schwacher Hitze 10 Minuten unter Rühren weich garen.", "Öl, geriebenen Knoblauch und Ingwer, dann das Berbere zugeben; 3 Minuten garen.", "Die gespülten Linsen und 750 ml Wasser zugeben.", "25 Minuten bei schwacher Hitze unter Rühren köcheln, bis die Linsen zerfallen; salzen.", "Mit Injera, Brot oder Reis servieren."]],
    "githeri-chapati": ["Githeri und Chapati", "Kenia", "1 h 30", "6 Personen", "Kenias Alltagsgericht: Mais und Bohnen mit Tomate und Gemüse geschmort, dazu blättrige Chapatis.", ["2 Tassen getrockneter weißer Mais und 1 Tasse Kidneybohnen, über Nacht eingeweicht (oder aus der Dose)", "2 Tomaten, 1 Zwiebel, 1 Karotte, 1 Kartoffel", "Chapati: 500 g Mehl", "1 Teelöffel Salz, 1 Esslöffel Zucker, 300 ml lauwarmes Wasser", "Öl, 1 Teelöffel Currypulver, Salz"], ["Den eingeweichten Mais und die Bohnen 1 Stunde in Wasser weich kochen; abgießen.", "Zwiebel, gewürfelte Karotte und Kartoffel im Öl anbraten, Tomaten und Curry zugeben, dann Mais und Bohnen; 15 Minuten schmoren.", "Chapati: Mehl, Salz, Zucker, 2 Löffel Öl und Wasser 10 Minuten kneten und 30 Minuten ruhen lassen.", "Den Teig ausrollen, mit Öl bestreichen, zu einer Rolle und dann zu einer Schnecke formen; ruhen lassen und zu dünnen Fladen ausrollen.", "Die Chapatis in einer trockenen Pfanne backen, beidseitig mit Öl bestreichen, bis sie goldbraun sind. Mit dem Githeri servieren."]],
    "bouye": ["Bouye (Baobab-Saft)", "Senegal", "15 min (+ 1 h kühlen)", "6 Personen", "Das Fruchtmark des Affenbrotbaums, zu einem cremigen, süß-säuerlichen Getränk verrührt und eiskalt serviert.", ["200 g Baobab-Fruchtpulver und 1 Liter kaltes Wasser", "250 ml gezuckerte Kondensmilch (oder 150 g Zucker)", "Zucker nach Geschmack", "1 Päckchen Vanillezucker", "Orangenblütenwasser oder eine Prise Muskat (nach Belieben)"], ["Das Baobabpulver in die Hälfte des kalten Wassers rühren und 15 Minuten stehen lassen.", "Gut verrühren, damit sich das Fruchtmark löst, dann durch ein feines Sieb gießen.", "Restliches Wasser, Kondensmilch, Zucker und Vanillezucker zugeben.", "Mit etwas Orangenblütenwasser oder Muskat aromatisieren.", "1 Stunde kühlen und eiskalt servieren."]],
    "to-sauce-gombo": ["Tô mit Okra-Soße", "Burkina Faso und Mali", "1 h", "6 Personen", "Der feste, glatte Hirsebrei aus Burkina Faso und Mali mit einer zähflüssigen Soße aus Okra, Fleisch und Soumbala.", ["500 g Hirse- oder Sorghummehl (oder Maismehl)", "500 g frische Okra oder 3 Esslöffel Okrapulver", "500 g Rind- oder Hammelfleisch in Stücken", "1 Esslöffel Soumbala (oder 1 Brühwürfel)", "2 Tomaten, 1 Zwiebel, Chili, Salz"], ["Soße: das Fleisch mit Zwiebel, Tomaten, Soumbala und Salz in 1 Liter Wasser 40 Minuten kochen.", "Die geschnittene Okra (oder das Pulver) und Chili zugeben; 15 Minuten unter Rühren kochen, bis die Soße Fäden zieht.", "Tô: ein Drittel des Mehls in 500 ml kaltem Wasser verrühren, in 1 Liter kochendes Wasser gießen und 10 Minuten unter Rühren kochen.", "Eine Schüssel dieses Breis abnehmen, dann das restliche Mehl einrieseln lassen und kräftig mit einem Spatel rühren; mit dem abgenommenen Brei lockern, wenn er zu fest ist.", "Zugedeckt 5 Minuten bei schwacher Hitze ziehen lassen, in einer nassen Schüssel zu Kugeln formen und mit der Soße servieren."]],
    "banku-okro": ["Banku mit Okrasuppe", "Ghana", "1 h", "6 Personen", "Ghanaisches Banku, ein leicht säuerlicher Teig aus fermentiertem Mais und Maniok, mit Okrasuppe und Fisch.", ["1 kg Banku-Mix (Teig aus Mais und Maniok)", "300 g Okra", "500 g Fisch (Tilapia oder Makrele) oder Rindfleisch", "3 Tomaten, 2 Zwiebeln, Chili, Ingwer", "2 Esslöffel gemahlene getrocknete Garnelen, 100 ml Palmöl, 1 Brühwürfel, Salz"], ["Banku: den Teig in etwa 750 ml Salzwasser glatt rühren.", "Bei mittlerer Hitze 20 Minuten ununterbrochen mit einem Spatel rühren, bis er dick und glatt ist; zu Kugeln formen.", "Suppe: eine Zwiebel im Palmöl anbraten, die mit der anderen Zwiebel, Ingwer und Chili pürierten Tomaten zugeben; 10 Minuten kochen.", "500 ml Wasser, Fisch, Garnelen und Brühwürfel zugeben; 10 Minuten kochen.", "Die Okra in Scheiben zugeben und 8 Minuten kochen. Mit dem Banku servieren."]],
    "sorrel": ["Sorrel (Weihnachtsgetränk)", "Jamaika", "30 min (+ 1 Nacht ziehen lassen)", "8 Personen", "Jamaikas rubinrotes Weihnachtsgetränk: Hibiskuskelche, mit viel Ingwer und Gewürzen aufgegossen und eiskalt serviert.", ["2 Tassen getrocknete Hibiskuskelche (Sorrel)", "1 großes Stück Ingwer, gerieben, und 2 Liter Wasser", "6 Gewürznelken, 1 Zimtstange, einige Pimentkörner", "1 Tasse Zucker", "Limettensaft; ein Schuss Rum (nach Belieben, für Erwachsene)"], ["Die Kelche abspülen.", "Das Wasser mit Ingwer, Nelken, Zimt und Piment aufkochen.", "Den Sorrel zugeben, den Herd ausschalten und zugedeckt über Nacht ziehen lassen.", "Abseihen, süßen und nach Geschmack Limettensaft zugeben.", "Auf Eis servieren, für Erwachsene mit einem Schuss Rum."]],
    "nnam-owondo": ["Nnam Owondo", "Kamerun", "1 Std. 30", "6 Personen", "Der Erdnusskuchen der Beti: gemahlene Erdnüsse mit Räucherfisch und Garnelen, in Bananenblättern gedämpft.", ["500 g rohe geschälte Erdnüsse (oder Erdnusspaste)", "100 g getrocknete Garnelen", "1 Räucherfisch", "Bananenblätter", "Chili, 1 Brühwürfel, Salz"], ["Die Erdnüsse leicht rösten, die Haut entfernen und mit etwas Wasser zu einer dicken Paste mahlen.", "Den zerpflückten Fisch, die gemahlenen Garnelen, Chili, Brühwürfel und Salz dazugeben.", "Die Masse einige Minuten kräftig schlagen.", "Auf über der Flamme erweichte Bananenblätter verteilen und gut verschließen.", "1 Stunde dämpfen. Mit Maniok, Kochbanane oder Maniokstangen servieren."]],
    "pain-patate": ["Pain Patate (Süßkartoffelkuchen)", "Haiti", "1 Std. 45", "8 Personen", "Der haitianische Kuchen aus geriebener Süßkartoffel, reifer Banane und Kokosmilch, mit Zimt, Ingwer und Vanille.", ["1 kg Süßkartoffeln", "2 reife Bananen", "400 ml Kokosmilch und 200 ml Kondensmilch (ungesüßt)", "150 g brauner Zucker, 50 g geschmolzene Butter, Rosinen", "Zimt, geriebener Ingwer, Muskat, Vanille"], ["Den Ofen auf 180 °C vorheizen und eine Form einfetten.", "Die Süßkartoffeln schälen und fein reiben; die Bananen zerdrücken.", "Mit Kokosmilch, Kondensmilch, Zucker, Butter und Gewürzen mischen.", "Die Rosinen dazugeben und in die Form gießen.", "1 Std. 15 backen, bis die Oberfläche goldbraun und fest ist. Lauwarm oder kalt servieren."]],
    "yuca-mojo": ["Yuca con mojo", "Kuba", "45 min", "4 Personen", "Maniok auf kubanische Art: weich gekocht und mit einer heißen Mojo-Soße aus Knoblauch, Zitrussaft und Zwiebel übergossen.", ["1 kg Maniok (Yuca), frisch oder tiefgekühlt", "8 Knoblauchzehen", "Saft von 2 Orangen und 2 Limetten", "1 Zwiebel in dünnen Ringen", "100 ml Olivenöl, 1 Teelöffel Kreuzkümmel, Salz"], ["Den Maniok schälen, in Stücke schneiden und die holzige Mitte entfernen.", "25 bis 30 Minuten in Salzwasser kochen, bis er aufplatzt; abgießen.", "Den Knoblauch mit Salz und Kreuzkümmel zerdrücken und im Orangen- und Limettensaft verrühren.", "Das Öl erhitzen, die Zwiebel darin 3 Minuten weich dünsten und die Knoblauchmischung neben dem Herd zugießen.", "Die heiße Mojo-Soße über den Maniok gießen und mit Schweinebraten oder Reis und Bohnen servieren."]],
}
